const wildlifeDialog=document.getElementById('wildlifeDialog'),wildlifeProfile=document.getElementById('wildlifeProfile');
document.querySelector('.wildlife-close').addEventListener('click',()=>wildlifeDialog.close());
animalGrid.addEventListener('click',event=>{const button=event.target.closest('[data-profile]');if(button)openWildlifeProfile(button.dataset.profile,!!button.dataset.profileSound)});
function profileSafe(value,fallback='Not recorded'){return String(value||fallback).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function countryName(code){try{return new Intl.DisplayNames([navigator.language||'en'],{type:'region'}).of(code)||code}catch{return code}}
async function profileJson(url){const response=await fetch(url);if(!response.ok)throw new Error(`${response.status}`);return response.json()}
const PROFILE_MEDIA_CACHE='pocketbook-wildlife-media-v1',PROFILE_MEDIA_INDEX='pocketbookWildlifeMedia';
const PROFILE_AUDIO_CACHE='pocketbook-wildlife-audio-v1',PROFILE_AUDIO_INDEX='pocketbookWildlifeAudio';
let pendingProfileMedia={};
let pendingProfileAudio={};
function readProfileMedia(){try{const value=JSON.parse(localStorage.getItem(PROFILE_MEDIA_INDEX)||'{}');return value&&typeof value==='object'&&!Array.isArray(value)?value:{}}catch{return{}}}
function writeProfileMedia(value){localStorage.setItem(PROFILE_MEDIA_INDEX,JSON.stringify(value))}
function readProfileAudio(){try{const value=JSON.parse(localStorage.getItem(PROFILE_AUDIO_INDEX)||'{}');return value&&typeof value==='object'&&!Array.isArray(value)?value:{}}catch{return{}}}
function writeProfileAudio(value){localStorage.setItem(PROFILE_AUDIO_INDEX,JSON.stringify(value))}
function savedAudioFor(scientific){return Object.values(readProfileAudio()).filter(item=>item.scientific===scientific)}
async function saveProfileAudio(button){const item=pendingProfileAudio[button.dataset.saveAudio];if(!item||!('caches'in window))return;button.disabled=true;button.textContent='Saving sound…';try{const response=await fetch(item.url,{mode:'no-cors',cache:'reload'});await(await caches.open(PROFILE_AUDIO_CACHE)).put(item.url,response);const index=readProfileAudio();index[item.id]={...item,savedAt:new Date().toISOString()};writeProfileAudio(index);button.textContent='✓ Saved offline';button.classList.add('saved')}catch(error){button.disabled=false;button.textContent='Retry save'}}
async function saveProfileMedia(scientific){const item=pendingProfileMedia[scientific],button=wildlifeProfile.querySelector('[data-save-profile-photo]');if(!item||!button||!('caches'in window))return;button.disabled=true;button.textContent='Saving photograph…';try{const response=await fetch(item.url,{mode:'no-cors',cache:'reload'});await(await caches.open(PROFILE_MEDIA_CACHE)).put(item.url,response);const index=readProfileMedia();index[scientific]={url:item.url,provider:item.provider,credit:item.credit,license:item.license,source:item.source,savedAt:new Date().toISOString()};writeProfileMedia(index);button.textContent='✓ Photograph saved offline';button.classList.add('saved');button.insertAdjacentHTML('afterend','<small class="profile-save-note">Attribution and source details were saved with this photograph.</small>')}catch(error){button.disabled=false;button.textContent='Retry saving photograph';button.insertAdjacentHTML('afterend','<small class="profile-save-note error">The photograph could not be saved. Check your connection and try again.</small>')}}
const observationGuides={
 Mammal:{identify:'Record overall size, body shape, coat pattern, horns or tusks, ear shape, tail and the way the animal moves.',behaviour:'Note whether it is alone, paired or in a group; record gait, posture, feeding, resting and interactions without approaching.',diet:'Record only food you actually see being eaten or handled. Browsing, grazing and scavenging can be confused from a brief view.',signs:'Look for tracks, dung, feeding remains, rubbed vegetation and paths, but do not identify sign from a single feature.',compare:'Compare body proportions, face, ears, tail, markings and movement with related species found in the same habitat.'},
 Bird:{identify:'Record size against a familiar object, bill shape, leg length, plumage pattern, flight silhouette and any clear call.',behaviour:'Note perch height, flight style, flock size, feeding method, display and association with water or mammals.',diet:'Record prey or plant material only when clearly observed; bill shape alone does not prove what an individual was eating.',signs:'Photograph feathers, nests or feeding remains without touching them or disturbing an occupied nest.',compare:'Compare bill, eye, legs, wing pattern, tail shape, call and habitat with similar birds; light can distort colour.'},
 Reptile:{identify:'From a safe distance record body proportions, head shape, scale pattern, colour, limbs and tail. Never handle an unknown reptile.',behaviour:'Note basking, shelter use, movement, defensive posture and proximity to water without provoking a response.',diet:'Record feeding only when directly observed. Do not approach a reptile or interfere with prey to obtain a better view.',signs:'Look for shed skin, tracks, slide marks, burrows and nesting traces; photograph in place and leave undisturbed.',compare:'Use several features—not colour alone—and obtain expert confirmation where venomous lookalikes are possible.'},
 Marine:{identify:'Record estimated length, body and fin shape, colour pattern, surfacing sequence and the position of any blow or dorsal fin.',behaviour:'Note group size, direction, dive interval, feeding, breaching and association with boats or other species.',diet:'Record prey only when clearly visible. Surface activity can have several explanations and should not be labelled as feeding automatically.',signs:'Log time, coordinates, water conditions, photographs and surfacing sequence; avoid collecting living animals or coral.',compare:'Compare silhouette, fin placement, markings, surfacing pattern and group behaviour; distance makes size estimates unreliable.'}
};
const speciesFieldGuides={
 'Leptailurus serval':{identify:'Slender, long-legged cat with very large rounded ears, a small head and a golden coat marked by black spots and stripes. The short tail is dark-ringed, and melanistic individuals can occur.',behaviour:'Usually solitary and most active from dusk through night, though daylight sightings occur. Watch for high listening postures, vertical pounces and careful movement through grass without drawing the cat toward a vehicle.',diet:'Takes mainly small vertebrates and invertebrates. Record a captured item only when clearly visible; a leap into cover does not by itself identify prey.',signs:'Rounded feline tracks normally show four toes and no claw marks, while scats may contain hair, feathers or insect remains. Track dimensions overlap with young caracal and other cats, so use a sequence and habitat context.',compare:'Caracal is heavier, plainer-coated and has long black ear tufts; African golden cat is stockier with proportionally shorter legs. Young cheetahs have a different build and longer tail.'},
 'Caracal caracal':{identify:'Medium-sized, strongly built cat with a largely plain tawny to reddish coat, pale underparts and conspicuous black-backed ears ending in long tufts. Facial lines are dark and the tail is shorter than the body.',behaviour:'Usually solitary and secretive, travelling and hunting mainly in low light. Record stalking, scent marking, listening and powerful leaps without using calls or food to change its course.',diet:'Takes birds and mammals across a broad size range, plus other available prey. Record direct prey evidence; feathers near a resting site are not automatically a caracal kill.',signs:'Broad rounded cat prints usually lack claw marks; scats, scrapes, urine marking and covered prey remains may occur. Spoor can overlap with serval and young leopard.',compare:'Serval has much longer legs, oversized rounded ears and bold spots; African golden cat is a forest cat with shorter ears and variable spotting. Lynx species are not native wild African look-alikes outside introduced or captive contexts.'},
 'Caracal aurata':{identify:'Compact forest cat with a relatively small head, rounded ears and coat varying from reddish or golden to grey, with spots ranging from obvious to nearly absent. The tail is moderately long and often dark-tipped.',behaviour:'Secretive and mainly solitary, moving on the forest floor and through dense cover. Record camera-trap time, gait and markings without baiting or clearing vegetation around a detection site.',diet:'Takes small mammals, birds and other animal prey. Use observed captures or identifiable remains; do not infer diet from a single photograph.',signs:'Feline tracks, scats, scrapes and prey remains are difficult to separate from other medium cats. Photographs, repeated measurements and local expert assessment are important.',compare:'Serval is taller and more boldly spotted with much larger ears; caracal is generally plainer and has long ear tufts. Coat colour alone is unreliable because African golden cats vary greatly.'},
 'Otocyon megalotis':{identify:'Small grey-brown fox with exceptionally large ears, a black facial mask, dark lower legs and a bushy tail with a dark tip. The muzzle is narrow and the body sits low compared with larger jackals.',behaviour:'Pairs or family groups forage with noses and ears directed to the ground, often changing activity with prey availability and temperature. Record digging, listening, resting and social contact without approaching dens.',diet:'Specialises heavily on insects, particularly termites, while also taking other invertebrates and small foods. Record the item or feeding site instead of assuming every digging bout targets termites.',signs:'Small canine tracks with claw marks, numerous shallow foraging holes, insect fragments in scat and multi-entrance dens. Tracks can resemble small foxes or jackals.',compare:'Cape fox has smaller ears relative to its head, lacks the strong facial mask and has different coat patterning; young jackals have longer proportions and less exaggerated ears.'},
 'Mellivora capensis':{identify:'Low, powerful mustelid with a broad pale-grey to white mantle running from the crown over the back and tail, sharply contrasting with black underparts. It has small ears, strong foreclaws and a short tail.',behaviour:'Mostly solitary, purposeful and often nocturnal, using claws to dig and investigate cavities. Give it space and never corner or follow closely; record gait, digging and scent marking from a vehicle or safe distance.',diet:'Opportunistically takes invertebrates, reptiles, small vertebrates, carrion and plant foods. Record direct feeding evidence and avoid repeating folklore as observation.',signs:'Five-toed tracks with long foreclaw impressions, deep conical digs, opened nests or burrows and coarse scat. Porcupine, aardvark and mongoose digging can overlap in appearance.',compare:'Striped polecats and zorillas show narrow white stripes and are much smaller; badgers elsewhere have different facial patterns. The broad continuous mantle and heavy build are distinctive.'},
 'Vulpes zerda':{identify:'Very small pale sandy fox with enormous ears, a delicate muzzle, dark eyes and a long bushy tail commonly ending in black. The hairy foot soles are not normally visible during observation.',behaviour:'Nocturnal family groups use burrow systems and emerge to listen and dig for food. Observe without illuminating dens continuously, blocking entrances or approaching dependent young.',diet:'Takes insects, small vertebrates, eggs and plant material, obtaining moisture from food. Record what is handled or eaten rather than inferring diet from digging alone.',signs:'Tiny canine tracks, fine claw marks, small scats and burrow complexes in sand. Wind rapidly erases sign, and other desert foxes may use similar ground.',compare:'Rüppell’s fox is larger with less extreme ear-to-head proportions and different facial markings; pale domestic dogs lack the fennec’s tiny build and huge ears.'},
 'Proteles cristata':{identify:'Slender, long-legged hyena relative with a yellowish to grey coat crossed by dark vertical stripes, a black-tipped mane and a bushy tail. The narrow head and small teeth suit its insect diet.',behaviour:'Usually solitary or paired and active after dark, walking slowly between insect patches and using communal latrines. Record mane raising, scent marking and foraging without spotlighting an animal for prolonged periods.',diet:'Feeds predominantly on termites licked from the surface and may take other insects. Do not describe excavated holes as aardwolf feeding unless direct evidence supports it.',signs:'Compact four-toed tracks with claws, well-used paths, den sites and conspicuous latrines containing insect-rich droppings. Spoor is smaller and narrower than that of large hyenas.',compare:'Striped and brown hyenas are far heavier with broader heads and feet; bat-eared fox is smaller, lacks a mane and has very large ears.'},
 'Felis nigripes':{identify:'Tiny, compact wild cat with a tawny coat densely marked by dark spots and bands, bold leg bars and black or very dark foot soles. The rounded face and short tail distinguish its proportions from many domestic cats.',behaviour:'Solitary, nocturnal and highly active while hunting, using cover, termite mounds and burrows by day. Observe without approaching dens or using bait; its small size makes distance estimates difficult.',diet:'Takes small mammals, birds and invertebrates. Record identifiable prey or direct captures, not assumptions based on hunting posture.',signs:'Very small rounded feline prints, scats and remains near shelter sites. Domestic and African wildcat tracks overlap strongly, so a track alone is inadequate identification.',compare:'African wildcat is larger, longer-legged and more lightly marked; domestic cats can resemble either species. Black soles, dense pattern, body proportions and verified locality must be assessed together.'},
 'Civettictis civetta':{identify:'Large, long-bodied civet with coarse grey coat, irregular black spots and bands, a black facial mask and an erectile dark dorsal crest. The ringed tail and high hindquarters give a distinctive outline.',behaviour:'Usually solitary and nocturnal, travelling on the ground along paths and scent-marking at repeated sites. Record route and posture without following into dense cover or approaching a cornered animal.',diet:'Omnivorous, taking fruit, invertebrates, small vertebrates, carrion and other foods. Record visible material; civet presence near refuse does not establish the full diet.',signs:'Five-toed prints may show claws, and repeated dung sites can contain seeds, hair and insect parts. Genets, mongooses and domestic animals can leave overlapping sign.',compare:'Genets are smaller and slimmer with longer, strongly ringed tails; African palm civet has a different body pattern and more arboreal appearance. Spotted hyena is much larger and differently proportioned.'},
 'Cryptoprocta ferox':{identify:'Long, muscular Madagascar carnivore with short reddish-brown fur, rounded ears, a long muzzle and a tail nearly as long as the body. Flexible ankles and semi-retractile claws support agile climbing.',behaviour:'Usually solitary, moving on the ground and in trees by day or night. Record climbing, scent marking and hunting without baiting, crowding or pursuing the animal.',diet:'Takes lemurs and other vertebrate prey. Identify prey only from direct observation or diagnostic remains; proximity to lemur groups is not proof of a hunt.',signs:'Five-toed cat-like tracks, scats at repeated marking sites, scratch marks and prey remains. Native and introduced carnivore spoor can be confused without measurements and local expertise.',compare:'Ring-tailed vontsira and introduced cats are smaller; domestic dogs have a different gait and non-retractile claw pattern. The fossa’s long body, powerful limbs and exceptionally long tail are key.'},
 'Suricata suricatta':{identify:'Small slender mongoose with a pointed face, dark eye patches, faint back bars, long foreclaws and a thin dark-tipped tail. It often stands upright on the hind legs while scanning.',behaviour:'Highly social groups forage together while sentinels watch, maintain burrow systems and care for young. Keep clear of burrow entrances and do not feed animals at habituated viewing sites.',diet:'Takes insects and other invertebrates, small vertebrates, eggs and plant material. Record items actually uncovered or swallowed; digging alone is not dietary evidence.',signs:'Clusters of small five-toed tracks, many shallow digs, scats and extensive multi-entrance burrows. Yellow mongooses and ground squirrels can share burrow areas.',compare:'Yellow mongoose is more uniformly yellow-red with a bushier pale-tipped tail; banded mongoose is larger, boldly barred and less upright in typical vigilance posture.'},
 'Parahyaena brunnea':{identify:'Large, shaggy hyena with long dark-brown hair, a pale mane and conspicuous horizontal striping on the legs. The sloping back, broad head and pointed ears distinguish its silhouette.',behaviour:'Mostly nocturnal and often solitary while foraging, though individuals share clan territories and den sites. Record travel, scent marking and carcass use without approaching dens or displacing an animal from food.',diet:'A scavenger that also takes available animal and plant foods, including coastal resources in some settings. Record actual feeding material; presence beside a carcass does not prove it made the kill.',signs:'Large four-toed tracks with claw marks, bone fragments, latrines, scent marks and paths to dens or carcasses. Track proportions overlap with spotted hyena and large canids.',compare:'Spotted hyena has a shorter coat and spotted pattern with rounded ears; striped hyena shows strong body stripes and a different mane. Low light can obscure all coat distinctions.'},
 'Gorilla beringei beringei':{identify:'Very large, powerfully built ape with long arms, a deep chest and black hair; mature males develop a broad silver-grey saddle across the back. The face, hands and feet are largely bare.',behaviour:'Lives in cohesive groups led by one or more adult males. Record feeding, resting, travel, play, grooming and vocal or chest-beating displays only from the distance set by guides.',diet:'Feeds mainly on leaves, shoots, stems and other plant material, with diet varying by place and season. Record the plant part actually handled rather than inferring food from nearby vegetation.',signs:'Large knuckle and foot impressions, bent or stripped vegetation, fibrous dung and temporary ground or tree nests. Ape nests and feeding traces overlap, so location and expert confirmation matter.',compare:'Eastern lowland gorilla is another form of eastern gorilla and cannot be separated safely by a brief field view alone. Chimpanzees are slighter, usually show less massive chests and make different nests and sign.'},
 'Gorilla gorilla gorilla':{identify:'Heavy forest ape with long arms, a broad chest and dark hair; adult males develop a silvery back and often a reddish crown. The face is comparatively broad with a pronounced brow.',behaviour:'Groups forage and rest in dense forest, while solitary males also occur. Note group composition, feeding height, nest use and vocalisations without following animals away from established viewing practice.',diet:'Takes fruit, leaves, stems and other plant foods, plus some invertebrate material. Record discarded fruit parts, chewed stems or directly observed feeding rather than assigning a food from habitat alone.',signs:'Knuckle prints, broad footprints, dung containing plant remains, broken stems and fresh day or night nests. Age sign by moisture and vegetation condition, but avoid touching it.',compare:'Other gorilla populations are best distinguished using geography and specialist evidence, not appearance alone. Chimpanzees are less massively built and their prints show different proportions.'},
 'Pan troglodytes':{identify:'Robust ape with long arms, dark hair and a bare face that varies with age and population. Adults lack a tail and often move by knuckle-walking, though they climb and walk upright for short distances.',behaviour:'Communities split into changing parties. Record pant-hoots, drumming, grooming, tool use, hunting or nesting without imitating calls, offering food or approaching.',diet:'Consumes fruit, leaves, seeds, insects and, at times, vertebrate prey. Only label an item when it is clearly seen or supported by diagnostic remains.',signs:'Knuckle and foot impressions, wadges of chewed plant fibre, cracked nuts or tool sites, dung with seeds and a new sleeping nest typically made each night. Do not enter or disturb nest sites.',compare:'Bonobos tend to be more gracile with longer-looking limbs and a darker face, but geography is essential. Gorillas are much heavier; baboons have tails and move as quadrupeds on palms rather than knuckles.'},
 'Pan paniscus':{identify:'Slender great ape with relatively long limbs, black hair, a dark face and hair that often parts centrally on the crown. There is no tail, and the body is generally less massive than a chimpanzee.',behaviour:'Lives in fluid communities with frequent social contact and changing foraging parties. Record posture, grooming, vocal exchanges, feeding and nest building without influencing movement.',diet:'Feeds heavily on fruit and also takes leaves, herbs, invertebrates and occasional vertebrate foods. Record direct evidence and avoid treating feeding ecology as identical at every site.',signs:'Knuckle and foot impressions, feeding remains, dung and constructed tree nests resemble chimpanzee evidence. Reliable separation normally requires location, repeated observation or expert analysis.',compare:'Chimpanzee is the principal look-alike; body build and facial impressions overlap. Bonobo identification must use verified locality together with multiple visible features.'},
 'Theropithecus gelada':{identify:'Large terrestrial primate with a short muzzle, a tufted tail and a conspicuous bare chest patch; adult males carry a long cape of hair over the shoulders. The fingers are adapted for precise grass picking.',behaviour:'Large multi-level bands spend much of the day sitting and feeding on open ground, then use cliffs as sleeping refuges. Note calls, lip displays, grooming and group spacing without blocking retreat routes.',diet:'Specialised largely for grasses, taking blades, seeds and underground parts, with other items varying seasonally. Record the plant part being selected rather than assuming every seated animal is feeding.',signs:'Narrow primate hand and foot prints, clipped grass patches, fibrous dung and well-used paths near feeding grounds or cliff roosts. Tracks alone do not distinguish it from baboons.',compare:'Hamadryas and other baboons have longer dog-like muzzles and lack the bare chest patch. Adult male geladas show the distinctive shoulder mantle and a shorter-looking muzzle.'},
 'Mandrillus sphinx':{identify:'Heavy forest monkey with a very short tail. Adult males have a massive head, blue-ridged muzzle, red nose and brightly coloured rump; females and young are smaller and much duller.',behaviour:'Forages on the forest floor in groups that may combine into very large aggregations. Record travel, digging, cheek-pouch use, grooming and threat displays without approaching feeding parties.',diet:'Takes fallen fruit, seeds, fungi, roots and animal matter. Note items placed in cheek pouches separately from items confirmed swallowed.',signs:'Hand and foot impressions, turned leaf litter, dug soil, opened hard fruits and dung containing seeds. Forest substrate often obscures tracks, and similar monkeys leave overlapping sign.',compare:'Drill lacks the adult male mandrill’s red-and-blue muzzle pattern. Baboons have longer tails and more uniformly dog-like faces; females and juveniles require locality and careful comparison.'},
 'Lemur catta':{identify:'Medium lemur with grey body, white face, dark eye patches and a long tail ringed boldly in black and white. It often holds the tail raised while moving on the ground.',behaviour:'Diurnal social groups travel both on the ground and in trees, sun-bask with limbs spread and use scent marking. Record group direction and alarm responses without surrounding animals.',diet:'Feeds on fruit, leaves, flowers and other plant parts, with opportunistic animal material. Record actual handling or ingestion and do not encourage close views with food.',signs:'Small hand-like prints, narrow paths, fruit remains, dung and scent-marking behaviour. The striped tail is more useful than spoor for confident field identification.',compare:'Other lemurs may share grey coats or facial masks but lack the complete black-and-white tail rings. Verreaux’s sifaka has a pale body, very long legs and distinctive sideways terrestrial hops.'},
 'Indri indri':{identify:'Large, virtually tailless lemur with long powerful hind limbs, rounded ears and variable black-and-white pelage. The small tail is unlike the long tails of most other lemurs.',behaviour:'Family groups move by strong vertical clinging and leaping and give far-carrying coordinated songs. Record song time, direction and group response without playback.',diet:'Feeds primarily on leaves with fruit, seeds and flowers also taken. Record the selected plant part; fallen fragments beneath a tree are not proof without observation.',signs:'Feeding fragments, dung, landing marks on soft ground and distinctive songs may reveal presence, while arboreal travel leaves little readable spoor.',compare:'Sifakas also cling and leap but possess long tails. Colour varies in indri, so tail length, proportions, voice and verified locality are more dependable than pelage alone.'},
 'Macaca sylvanus':{identify:'Sturdy, tailless macaque with yellowish-brown to grey fur, a pale or pinkish face and strong limbs. The tail is reduced to a small vestige rather than visibly projecting.',behaviour:'Multi-male, multi-female troops forage on the ground and in trees. Record grooming, infant carrying, feeding and alarm behaviour without offering food or drawing animals toward roads.',diet:'Omnivorous, taking leaves, roots, fruit, seeds and invertebrates according to season and site. Human food changes behaviour and must never be used as observation evidence.',signs:'Hand and foot prints, opened cones or fruit, dug ground, dung and sleeping-site use. Human-associated sign can be misleading where troops visit developed areas.',compare:'Baboons have long muzzles and visible tails. Other macaques are not native to Africa; the nearly tailless form and verified North African locality support identification.'},
 'Chlorocebus pygerythrus':{identify:'Slender grey-green monkey with a black face bordered by pale fur, pale underparts and a long tail. Adult males show distinctive blue and red genital colour when visible.',behaviour:'Active troops feed and travel on the ground and in trees, using distinct alarm calls and frequent social grooming. Observe from a distance, particularly around camps where food conditioning is possible.',diet:'Takes fruit, seeds, leaves, flowers and invertebrates, and may exploit crops or refuse. Record natural and human-derived foods separately.',signs:'Small hand and foot prints, fruit remains, dung and troop alarm calls. Similar guenons make comparable sign, so tracks alone rarely identify the species.',compare:'Tantalus, grivet and green monkeys are closely related and superficially similar. Face border, limb and tail colour plus verified geography should be checked together.'},
 'Colobus guereza':{identify:'Large black-and-white leaf monkey with a white facial fringe, white shoulder mantle and a long tail ending in a conspicuous white plume. The thumb is greatly reduced but seldom visible in the field.',behaviour:'Arboreal groups rest and feed in tree crowns and males give deep roaring calls. Record canopy route, leaps, group size and calls without playback or positioning beneath animals.',diet:'Feeds heavily on leaves, supplemented by fruit, seeds and flowers. Record the plant part directly; time spent in a fruiting tree does not alone establish feeding.',signs:'Dropped leaf or fruit fragments, dung beneath feeding or sleeping trees and resonant calls are common clues. Ground tracks are unusual and not a reliable survey method.',compare:'Angola colobus and other black-and-white colobus differ in the distribution and length of white fringes and tail hair. A clear photograph and locality are usually needed.'},
 'Erythrocebus patas':{identify:'Long-limbed, slender terrestrial monkey with reddish-brown upperparts, pale underparts, a pale moustache and a long tail. Adult males are substantially larger than females.',behaviour:'Fast-moving groups range widely through open country and often scan from raised ground or vegetation. Record route, spacing, vigilance and feeding without pursuit.',diet:'Takes gums, seeds, fruit, flowers and many invertebrates. Record the precise item or foraging action; rapid ground searching does not prove prey capture.',signs:'Small narrow primate prints, dug or disturbed soil, opened pods and dung along travel routes. Spoor can overlap with vervets and baboons.',compare:'Vervet monkeys are greyer, less long-limbed and more arboreal; patas shows a reddish back, pale face pattern and coursing build. Juveniles require extra caution.'},
 'Struthio camelus':{identify:'Very large flightless bird with a long bare neck, powerful legs and only two toes on each foot. Adult males are mainly black and white; females and young birds are greyer brown.',behaviour:'Record walking, running, dust bathing, courtship and nest attendance from a distance. Adults guarding eggs or chicks can defend forcefully.',diet:'Takes seeds, leaves, flowers, fruit and small animal matter. Record swallowed items only when visible; ground pecking alone is not diagnostic.',signs:'Large two-toed footprints, shallow nest scrapes, substantial droppings and eggshell fragments. Do not collect material at protected or archaeological sites.',compare:'Somali ostrich may show different skin colour and occurs mainly in northeastern Africa; location and specialist references are needed where identification is uncertain.'},
 'Sagittarius serpentarius':{identify:'Very tall terrestrial raptor with long bare legs, grey body, black flight feathers and tail, red-orange facial skin and a crest of elongated dark feathers.',behaviour:'Usually walks through open country while searching for prey, sometimes in pairs. Record deliberate stepping, stamping, short pursuit and soaring without forcing flight.',diet:'Takes insects and small vertebrates, including reptiles. Record prey directly; it is not exclusively a snake hunter.',signs:'Large walking tracks, pellets, feathers and substantial stick nests in flat-topped trees. Tracks alone are difficult to separate from other large ground birds.',compare:'Cranes and bustards lack the hooked raptor bill and red facial skin. In flight, long legs project behind and elongated central tail feathers are visible.'},
 'Haliaeetus vocifer':{identify:'Large, heavy eagle with a white head, breast and tail contrasting with chestnut body and dark wings. Adults have a yellow face and strongly hooked bill; juveniles are mottled brown.',behaviour:'Often perches conspicuously beside water and calls in pairs. Record fishing attempts, piracy from other birds, territorial calling and perch use without approaching nests.',diet:'Frequently takes fish but also captures birds and other available prey or scavenges. Record the item directly rather than assuming every water-side strike caught fish.',signs:'Fish remains, pellets, whitewash beneath favourite perches and large stick nests near water. These signs are not exclusive to this eagle.',compare:'Palm-nut vulture has extensive white plumage but different wing pattern and bare facial skin. Juvenile fish eagles require comparison with other large brown eagles.'},
 'Polemaetus bellicosus':{identify:'Very large eagle with dark brown head and upperparts, pale underparts marked with dark spots, long broad wings and a short barred tail. Juveniles are much paler.',behaviour:'Often soars high or watches from exposed perches. Record hunting approach, prey response and nest activity from far enough away to avoid disturbance.',diet:'Takes a wide range of birds, reptiles and mammals. Identify prey only from direct observation or diagnostic remains.',signs:'Large stick nests in tall trees or structures, pellets, feathers and prey remains. Nest occupation must be confirmed without close approach.',compare:'Crowned eagle has shorter, broader wings and is more forest-associated; Verreaux’s eagle is mostly black with a white back marking. Juveniles demand extra caution.'},
 'Terathopius ecaudatus':{identify:'Distinctive short-tailed eagle with very long wings, black body, chestnut mantle, grey shoulder patches and bright red face and feet in adults. Sexes differ in wing pattern.',behaviour:'Spends long periods in low rocking flight with wings held slightly raised. Record flight direction, searches, display and scavenging without using colour alone at distance.',diet:'Takes small vertebrates, carrion and other animal material. Record the item directly; circling over a carcass does not prove feeding.',signs:'Large stick nest, pellets, feathers and remains near perches, though ground evidence is rarely diagnostic.',compare:'Short tail and rocking flight distinguish adults from most eagles. Juveniles are brown and can resemble snake-eagles or other immature raptors.'},
 'Ephippiorhynchus senegalensis':{identify:'Enormous black-and-white stork with a long red-and-black bill crossed by a yellow frontal saddle. Adults have long dark legs; eye colour differs between sexes.',behaviour:'Usually walks slowly through shallow wetlands alone or in pairs. Record probing, striking, territorial display and flight without entering feeding shallows.',diet:'Takes fish, frogs, reptiles, crustaceans and other aquatic prey. Record captured prey when visible rather than inferring from bill movements.',signs:'Large long-toed tracks in mud, feeding probes and a substantial stick nest in a tall tree. Similar wetland birds can leave overlapping spoor.',compare:'Woolly-necked stork is much smaller with a pale neck; black stork lacks the saddle-shaped bill marking. Jabiru does not occur naturally in Africa.'},
 'Bucorvus leadbeateri':{identify:'Huge ground-dwelling hornbill with black plumage, white primary feathers visible in flight and bare red facial and throat skin in adults. Females show a violet-blue throat patch.',behaviour:'Family groups walk and forage together and give deep booming calls. Record group size, cooperative feeding and roost movement without approaching nest cavities.',diet:'Takes insects and other small animals, plus occasional plant material. Record prey directly because searching and handling can obscure the item.',signs:'Large four-toed walking tracks, pellets, feathers and large tree cavities used for nesting. Do not inspect or touch active cavities.',compare:'Abyssinian ground hornbill occurs mainly farther north and has blue facial areas; flying birds can resemble large dark storks until the white primaries show.'},
 'Coracias caudatus':{identify:'Stocky roller with lilac breast, turquoise belly and wing panels, greenish head, rufous face and elongated outer tail feathers in adults. Colours change strongly with light.',behaviour:'Often watches from exposed perches before dropping to the ground for prey. Record perch choice, rolling display, prey capture and territorial calls.',diet:'Takes insects and small vertebrates. Record visible prey; repeated ground drops do not identify the food item.',signs:'Pellets and insect remains may occur beneath favoured perches; nests are in tree cavities. Neither sign should be assigned without direct association.',compare:'Lilac-throated roller has different head and breast pattern and a more restricted western distribution. European roller lacks the lilac breast and tail streamers.'},
 'Balaeniceps rex':{identify:'Very large grey wetland bird with exceptionally broad shoe-shaped bill, long legs, a slight rear crest and an intense pale-eyed stare. It often stands motionless.',behaviour:'Usually solitary in dense swamp vegetation. Record prolonged stillness, slow steps, lunging strikes and bill-clattering from a respectful distance.',diet:'Takes fish and other wetland vertebrates. Record prey only when visible; an unsuccessful strike should not be assigned a target.',signs:'Very large long-toed tracks, flattened vegetation, droppings and broad nests on wetland vegetation. Avoid entering nesting habitat.',compare:'Pelicans have a flexible pouch and different posture; hamerkop is far smaller and brown. From behind, bill size and head profile remain important.'},
 'Phoenicopterus roseus':{identify:'Very tall pale pink-and-white flamingo with a pink bill ending in black, long pink legs and crimson-and-black wings visible in flight.',behaviour:'Forms flocks that feed by sweeping an inverted bill through water. Record flock movement, display, flight lines and disturbance without approaching breeding concentrations.',diet:'Filters small aquatic organisms and plant material. Record feeding method and water conditions rather than claiming a specific food without sampling evidence.',signs:'Webbed footprints, parallel feeding traces in soft substrate, feathers and mud nest mounds at colonies. Breeding sites are highly disturbance-sensitive.',compare:'Lesser flamingo is smaller and usually deeper pink, with a much darker bill. Size is difficult at distance, so bill pattern and mixed-flock comparison help.'},
 'Ardeotis kori':{identify:'Massive ground bird with long legs, mottled brown-grey body, barred neck and a small crested head. Males are substantially larger and can inflate the neck in display.',behaviour:'Walks slowly through open country and usually flies only when necessary. Record foraging, vigilance and courtship without driving the bird into flight.',diet:'Omnivorous, taking insects, small vertebrates and plant material. Record visible items; pecking alone does not establish diet.',signs:'Large three-toed tracks, droppings, dust-bathing scrapes, feathers and shallow ground nests. Avoid approaching a sitting bird.',compare:'Denham’s bustard is smaller and shows different neck and wing pattern. Female kori bustards can overlap large bustards in apparent size at distance.'},
 'Rynchops flavirostris':{identify:'Long-winged river bird with black upperparts, white underparts and a bright bill whose lower mandible projects beyond the upper. The short legs are red.',behaviour:'Feeds by flying low over calm water with the lower bill cutting the surface. Record feeding lines, flock roosts and breeding activity without approaching sandbanks.',diet:'Takes small fish and aquatic prey encountered while skimming. Record captures only when visible; surface contact does not always mean success.',signs:'Three-toed tracks, shallow nest scrapes and colonies on exposed sandbanks. Human footprints or boat landings near colonies indicate disturbance risk.',compare:'Terns have equal bill mandibles and usually plunge-dive rather than skim continuously. At rest, the unique lower mandible is diagnostic when visible.'},
 'Aepyceros melampus':{identify:'Medium-sized, lightly built antelope with a reddish-brown back, pale underside and black markings on the rump, tail and rear legs. Only males carry long lyre-shaped horns.',behaviour:'Forms female herds, bachelor groups and territorial associations that change with season and conditions. Record alarm snorts, high leaps, grooming and habitat-edge use.',diet:'A flexible mixed feeder that grazes and browses. Record the plant part actually taken before describing the feeding mode.',signs:'Small pointed cloven tracks, pellet dung, browsed or grazed vegetation, resting forms and repeated paths between cover and water.',compare:'Springbok has a white face, dark flank stripe and dorsal fan. Puku and lechwe lack the impala’s black rump and heel markings.'},
 'Tragelaphus strepsiceros':{identify:'Large, long-legged antelope with narrow white body stripes, very large ears and a pale facial chevron. Adult males carry long spiral horns and a shaggy throat fringe.',behaviour:'Usually seen singly or in small loose groups. Record browsing, stillness in cover, alarm barking and male displays without driving animals from thickets.',diet:'Browses leaves, shoots, herbs, pods and fruit. Record plant use directly because feeding varies with habitat and season.',signs:'Large narrow cloven tracks with pointed tips, sizeable pellet dung, browsed shrubs, beds in cover and trails through thickets.',compare:'Lesser kudu is smaller with more body stripes. Nyala shows stronger sexual colour differences and males have shaggier coats and yellow lower legs.'},
 'Connochaetes taurinus':{identify:'Large antelope with heavy forequarters, sloping back, broad muzzle, dark vertical shoulder bars, curved horns in both sexes and a long dark tail.',behaviour:'Occurs in herds of changing size. Record grazing, rutting, calf groups, river approaches and coordinated movement without blocking travel routes.',diet:'Mainly grazes short and medium grasses. Record feeding height and habitat rather than inferring a grass species.',signs:'Broad cloven tracks, abundant dung in herd areas, trampled routes and grazing lawns. Mixed herds can make attribution difficult.',compare:'Black wildebeest has a pale horse-like tail, forward-curving horn tips and a more uniformly dark body. Buffalo is heavier with broader horn bases.'},
 'Hippotragus niger':{identify:'Large, powerfully built antelope with long ringed horns sweeping backward, a stiff upright mane and bold black-and-white facial pattern. Adult males are usually darkest.',behaviour:'Commonly forms female-and-young groups led by a territorial male, with bachelor groups elsewhere. Record group structure, vigilance and access to water from a distance.',diet:'Predominantly grazes medium-to-tall grasses and may browse occasionally. Record the vegetation actually cropped.',signs:'Large rounded cloven tracks, substantial pellet dung, grazed patches, beds and paths linking woodland, grass and water.',compare:'Roan antelope is generally paler, has a darker facial mask with white eyebrows and less strongly contrasting body colour. Horn shape overlaps.'},
 'Hippotragus equinus':{identify:'Very large antelope with a grey-brown to reddish coat, black-and-white face, long ears with dark tufts and strongly ringed horns curving backward.',behaviour:'Usually in small herds with a dominant male or in bachelor groups. Note alert posture, grazing, resting shade and water visits without cutting off escape routes.',diet:'Primarily grazes grasses but may browse. Direct feeding observations are more reliable than habitat-based assumptions.',signs:'Large cloven tracks, pellet dung, grazing traces, resting sites and regular trails near water.',compare:'Sable antelope is typically darker and has a more sharply contrasted pale face. Female sable can resemble roan, so face, ear and coat characters should be combined.'},
 'Taurotragus oryx':{identify:'Africa’s largest antelope, heavy-bodied yet long-legged, with a tan to grey coat, shoulder hump, throat dewlap and tightly spiralled horns in both sexes.',behaviour:'Occurs singly or in herds that can become large. Record group composition, clicking movement, browsing height and calf position without compressing the herd.',diet:'A mixed feeder taking leaves, shoots, fruit and grasses. Record visible plant use rather than assigning diet from spoor alone.',signs:'Very large rounded cloven tracks, sizeable pellet dung, high browsing, resting depressions and broad herd paths.',compare:'Greater kudu is more slender, has prominent white stripes and males carry wider open spirals. Domestic cattle have different horn structure and human association.'},
 'Antidorcas marsupialis':{identify:'Small-to-medium gazelle-like antelope with a white face, dark side stripe, white belly and a folded white dorsal fan that can open during display. Both sexes carry ringed horns.',behaviour:'Forms flexible herds and may perform high stiff-legged leaps. Record pronking, territorial marking, grazing and group movement without provoking flight.',diet:'Grazes and browses, including moisture-rich plants in dry areas. Record the plant material actually taken.',signs:'Small narrow cloven tracks, pellet dung, short grazing and territorial dung or urine marks.',compare:'Impala lacks the broad dark flank stripe and white dorsal fan. Thomson’s gazelle has a different facial pattern and occurs mainly farther north and east.'},
 'Oryx gazella':{identify:'Large desert-adapted antelope with very long straight horns, grey-fawn body, black-and-white face, dark flank markings and black upper legs.',behaviour:'Often travels in groups across open dry country. Record shade use, digging, feeding and herd spacing without pursuing animals in heat.',diet:'Feeds on grasses, herbs, roots, bulbs and browse according to conditions. Record direct use, particularly excavated foods.',signs:'Large pointed cloven tracks, pellet dung, excavations for roots or bulbs, resting scrapes and long travel lines.',compare:'East African oryx has different flank and leg patterning and occurs farther northeast. Addax is paler with spiralled horns and does not naturally overlap most gemsbok range.'},
 'Kobus ellipsiprymnus':{identify:'Large shaggy antelope with a grey-brown coat, pale eye and muzzle markings and heavily ringed horns in males. Common waterbuck shows a white rump ring; defassa form has a solid white rump patch.',behaviour:'Often remains near dependable water but may feed some distance away. Record territorial males, female groups, resting and water use.',diet:'Predominantly grazes grasses and may take other vegetation. Record grass height and plant parts when feeding is visible.',signs:'Large splayed cloven tracks, coarse pellet dung, grazed areas and paths connecting cover, feeding areas and water.',compare:'Puku and lechwe are smaller and less shaggy. Rump pattern separates common and defassa forms but should not be used to infer precise boundaries.'},
 'Kobus leche':{identify:'Medium-sized wetland antelope with elongated spreading hooves, reddish to tawny coat and pale underparts. Males carry long ridged horns; lower legs often show dark markings.',behaviour:'Closely associated with floodplains and shallow water. Record herd structure, territorial activity and movement through water without forcing crossings.',diet:'Grazes floodplain and aquatic-edge grasses. Record water depth and the vegetation cropped when observable.',signs:'Elongated splayed hoofprints in soft mud, pellet dung, trampled wetland paths and cropped floodplain grasses.',compare:'Puku is more uniformly golden and less specialised for deep wet ground. Nile lechwe is darker and has different markings; location and sex matter.'},

 'Acinonyx jubatus':{identify:'Tall, lightly built cat with long legs, a small rounded head, solid black spots and dark tear marks from each eye toward the mouth. The long tail is usually ringed near its tip.',behaviour:'Often scans from raised ground. Females are commonly solitary except with cubs; males may form coalitions. Never pressure a resting animal or interfere with a pursuit.',diet:'Primarily hunts small-to-medium antelope and other vertebrates. Record prey only when directly seen; presence beside a carcass does not prove the cheetah made the kill.',signs:'Compact cat tracks may show claw tips because the claws are less retractile. Scat and scent marks can occur on prominent trees, mounds or other landmarks.',compare:'Leopard is heavier, has rosettes instead of solid spots and lacks tear marks. Serval has much larger ears, a shorter tail and proportionally longer legs.'},
 'Lycaon pictus':{identify:'Long-legged canid with very large rounded ears, a white-tipped tail and an individually unique patchwork coat of black, tan, brown and white.',behaviour:'Highly social packs rest, greet, rally and travel together. Record pack size, pups and coordinated movement without separating animals or following a hunt closely.',diet:'Packs hunt medium-sized antelope and other vertebrate prey. Record directly observed prey; feeding is rapid and carcass evidence can disappear quickly.',signs:'Dog-like four-toed tracks with visible claws, communal resting sites, scattered scat and well-used travel routes. Domestic dog tracks require careful exclusion.',compare:'Spotted hyena has a sloping back and rounded ears. Jackals are much smaller and lack the irregular multicoloured coat.'},
 'Crocuta crocuta':{identify:'Powerful carnivore with rounded ears, broad muzzle, high shoulders and a back sloping toward shorter hindquarters. The sandy to grey-brown coat has irregular dark spots.',behaviour:'Lives in complex clans but may travel alone. Record greeting, whooping, scent marking and den activity without approaching cubs or feeding animals.',diet:'Both hunts and scavenges. Direct observation is required before assigning a kill; pale fragmented dung can reflect consumption of bone.',signs:'Broad four-toed tracks usually show claws; foreprints are larger than hindprints. Look for pale bone-rich scat, latrines, hair and dens.',compare:'Brown hyena has long shaggy dark fur and striped legs. African wild dog has huge ears, a patchwork coat and more even body proportions.'},
 'Giraffa camelopardalis':{identify:'Extremely tall browser with a long neck and legs, sloping back, horn-like ossicones and a patterned coat. Pattern and lower-leg markings vary among populations.',behaviour:'Loose groups change composition frequently. Record browsing height, vigilance, necking, calf position and drinking posture while leaving water access clear.',diet:'Browses leaves, shoots, flowers and pods. Record the plant and feeding height only when visible rather than assuming acacia use.',signs:'Very large divided hoofprints, high browse lines, stripped twig tips, pellet dung and long-stride pathways.',compare:'No other living African mammal shares its height. Coat pattern alone should not assign a giraffe species or subspecies without geographic and expert support.'},
 'Hippopotamus amphibius':{identify:'Massive semi-aquatic mammal with barrel-shaped body, very short legs, broad muzzle and eyes, ears and nostrils set high on the head.',behaviour:'Usually rests in water by day and travels onto land to feed, often after dark. Treat water edges and paths as high-risk and never stand between a hippo and water.',diet:'Primarily grazes grasses on land. Aquatic resting does not mean aquatic plants are its principal food.',signs:'Four-toed tracks, broad paths between water and grazing, clipped grass and dung spread by tail-fanning. Fresh paths may be active at night.',compare:'Pygmy hippopotamus is much smaller, more solitary and associated with dense forest and swamp habitat.'},
 'Equus quagga':{identify:'Stocky horse-shaped grazer with bold black-and-white striping, upright mane and tufted tail. Each individual pattern differs.',behaviour:'Often forms stable family groups within larger herds. Record grooming, vigilance, stallion herding, dust bathing and association with other grazers.',diet:'Predominantly grazes grasses and can crop coarser growth. Record bite height and vegetation only when clearly observed.',signs:'Single-hoof tracks, fibrous dung, grazing lawns, dust baths and trails to water. Tracks overlap domestic horses and donkeys.',compare:'Grévy’s zebra has narrower stripes, a white belly and very large rounded ears. Mountain zebra has a grid-like rump pattern and throat dewlap.'},
 'Phacochoerus africanus':{identify:'Robust pig with broad flattened head, facial warts, upward-curving tusks, sparse mane and a tail held upright while running. Adults often kneel to graze.',behaviour:'Family groups commonly feed together; males may be solitary. Record kneeling, rooting, wallowing and reverse entry into burrows without crowding occupied holes.',diet:'Mostly grazes but also takes roots, bulbs and fruit. Disturbed soil alone does not establish what was eaten.',signs:'Rounded two-toed tracks often show dewclaws in soft ground, rooted soil, dung, wallows and burrows modified from aardvark holes.',compare:'Bushpig is hairier, usually darker, has a longer facial profile and lacks the same prominent facial warts and upright running tail.'},
 'Crocodylus niloticus':{identify:'Large crocodilian with a broad robust snout, heavily armoured back and powerful tail. Colour varies from olive to dark grey-brown.',behaviour:'Basks at water margins and floats with eyes and nostrils exposed. Keep well back from every shoreline and never approach nests or young.',diet:'An opportunistic predator taking aquatic and terrestrial animals. A submerged or floating animal is not proof of hunting.',signs:'Five-toed foreprints, four-toed hindprints, belly or tail drags, slides, basking marks and nests above the waterline.',compare:'West African crocodile is externally very similar and identification depends heavily on geography and expert assessment; slender-snouted crocodiles have a much narrower snout.'},

 'Loxodonta africana':{identify:'Very large body, pillar-like legs, deeply concave back, huge fan-shaped ears and two finger-like projections at the trunk tip. Tusks vary and are not a safe basis for sexing.',behaviour:'Watch family groups led by experienced females, adult bulls alone or in loose associations, trunk contact, ear position, dust bathing and access to water. Give every elephant an escape route.',diet:'A mixed feeder that takes grasses, leaves, bark, roots and fruit. Record the plant part actually handled rather than inferring diet from damaged vegetation.',signs:'Large round foreprints, more oval hindprints, fibrous dung, stripped bark, broken branches, dusting sites and well-used paths. Fresh sign means elephants may be close.',compare:'African forest elephant is generally smaller with rounder ears and straighter, downward-pointing tusks; the two should be separated with range and expert evidence, not size alone.'},
 'Panthera leo':{identify:'Large, powerfully built cat with a plain tawny coat, rounded ears and a black-tufted tail. Adult males often have a mane; females and young males may not.',behaviour:'Record group composition, resting, social greeting, scent marking, roaring and hunting attempts. Lions rest for long periods, so time and repeated observation matter.',diet:'Primarily hunts medium-to-large mammals and also scavenges. Identify prey only from direct observation or diagnostic remains; avoid assuming every carcass was killed by lions.',signs:'Broad rounded tracks usually without claw marks, three-lobed rear pad, scrapes, scent marks, hair and large segmented scat. Tracks alone do not establish pride size.',compare:'Leopard is smaller and rosetted; cheetah is slender with solid spots and facial tear marks. A lioness at distance can be confused with a large plain-coloured cat without scale.'},
 'Panthera pardus':{identify:'Muscular cat with a long tail and dark rosettes rather than solid spots. The face and lower legs carry smaller solid markings; coat colour varies with habitat and light.',behaviour:'Usually encountered alone. Note stalking, scent marking, tree use, alarm calls from prey and whether food has been moved or cached. Do not approach a resting leopard.',diet:'An adaptable predator taking prey from small vertebrates to antelope, and sometimes scavenging. Record prey remains cautiously because other predators may use the same carcass.',signs:'Round tracks with four toes and usually no claw marks, scrapes, scat placed along routes, claw marks and cached prey. Front tracks are broader than hind tracks.',compare:'Cheetah has solid spots, a smaller head, long legs and dark tear marks; jaguar does not occur wild in Africa. Spotted hyena has a dog-like print with visible claws.'},
 'Syncerus caffer':{identify:'Heavy bovine with dark coat, broad muzzle and thick horns. Mature bulls may develop a fused horn boss; females and younger animals have lighter, less massive horns.',behaviour:'Observe herd spacing, calves, bachelor bulls, wallowing and alert posture. Solitary bulls and animals hidden in dense cover require exceptional distance and care.',diet:'Predominantly grazes grasses and depends on regular water in many landscapes. Record grazing height and habitat rather than attributing a specific grass species without confirmation.',signs:'Large cloven hoofprints with rounded toes, flattened grazing lawns, dung pats, mud wallows and rubbed vegetation. Tracks can overlap cattle; context and measurements help.',compare:'Domestic cattle vary greatly but often show human association or branding. Eland is taller and more lightly built, with spiral horns and a different track shape.'},
 'Diceros bicornis':{identify:'Two-horned rhinoceros with a pointed, prehensile upper lip adapted for browsing. Head carriage is relatively high; horn size and shape are individually variable.',behaviour:'Often solitary except for mothers with calves and temporary associations. Note browsing, dung middens, urine spraying and ear position from a very safe distance.',diet:'Browses woody plants, shrubs and herbs, using the hooked lip to grasp stems. Record clipped twigs or directly observed feeding; plant identification needs care.',signs:'Three-toed tracks, large dung middens containing woody fragments, broken browse, rubbed posts and well-used paths. Never follow fresh sign on foot without a qualified guide.',compare:'White rhinoceros has a broad square grazing lip, generally lower head carriage and a different feeding posture. Horns alone cannot reliably separate the species.'},
 'Ceratotherium simum':{identify:'Very large rhinoceros with a broad square upper lip, long head and pronounced shoulder hump. It commonly carries the head low while grazing.',behaviour:'May occur alone or in small associations; territorial bulls use dung middens and urine marking. Record resting, grazing and social spacing without altering its movement.',diet:'A specialised grazer using the broad lips to crop short grasses. Record feeding posture and grass height rather than inferring a particular plant species.',signs:'Three-toed tracks, broad grazing paths, dung middens with finely cut grass, wallows and rubbing posts. Fresh sign warrants distance and professional guidance.',compare:'Black rhinoceros has a pointed hooked browsing lip and commonly holds the head higher. Body size, colour and horn length overlap and are unreliable on their own.'},
 'Crocodylus suchus':{identify:'Broad-snouted crocodile closely resembling the Nile crocodile, with a heavily armoured body and dark cross-banding most evident in younger animals. Field appearance alone is often insufficient for a confident separation.',behaviour:'Basks at water edges and retreats rapidly when disturbed; individuals may float with only eyes and nostrils visible. Observe from a secure bank or vessel and never approach a nest or haul-out site.',diet:'Takes aquatic and terrestrial prey according to size. Record only a clearly observed capture or feeding event; proximity to fish or mammals is not evidence of feeding.',signs:'Look for broad belly slides, clawed footprints, tail drag, haul-out paths and nests above the waterline. Do not follow fresh sign through waterside vegetation.',compare:'Nile crocodile is extremely similar and identification normally needs locality, detailed morphology or expert evidence. Snout width seen at an angle is unreliable.'},
 'Varanus niloticus':{identify:'Large, powerfully built monitor with a long laterally compressed tail, elongated neck and patterned dark body bearing pale spots or bands. The nostrils sit nearer the eye than the tip of the snout.',behaviour:'Strong swimmer and climber that often basks near water before entering it when alarmed. Keep escape routes open and do not corner or attempt to handle one.',diet:'Consumes a wide variety of animal prey, eggs and carrion. Record identifiable food directly; digging at a bank does not prove nest predation.',signs:'Five-toed tracks show long claw marks, often with a central tail drag; burrows, disturbed nests and slide marks may occur near water.',compare:'Rock monitor is generally more terrestrial, heavier-bodied and has nostrils nearer the snout tip. Young crocodiles have a different gait, foot pattern and body carriage.'},
 'Python sebae':{identify:'Very large, heavy-bodied python with an arrow-shaped head marking and an irregular brown, olive and tan pattern. The head is distinct from the neck and heat-sensing pits line the lips.',behaviour:'Usually relies on concealment and may bask or move between cover and water. Never approach closely, step over, touch or block the retreat of any large snake.',diet:'Constrains vertebrate prey of varying size. Record feeding only from a safe distance and do not interfere with either predator or prey.',signs:'A broad sinuous trail, smooth slide through dust, shed skin and compressed vegetation may indicate a large snake, but rarely identify species alone.',compare:'Southern African python is closely related and best separated with geography and expert taxonomy. Puff adders are far shorter and stouter with a strongly triangular patterned head.'},
 'Dendroaspis polylepis':{identify:'Long, slender snake with smooth-looking grey, olive or brown body, coffin-shaped head and a pale to dark mouth interior that may be exposed defensively. It is not normally black-bodied.',behaviour:'Fast-moving and often retreats if given space, but may raise the forebody and gape when threatened. Remain well back, never pursue it and alert a trained local responder if it is near people.',diet:'Takes mainly warm-blooded vertebrates. A snake entering a hole may be seeking shelter rather than prey, so avoid inferring a hunt.',signs:'Long narrow tracks in sand, shed skins and refuge use are not diagnostic. Photograph only from a safe distance with a long lens.',compare:'Green mambas are green and more strongly associated with trees; boomslang has a shorter head, very large eyes and different scaling. Colour alone never establishes a safe identification.'},
 'Bitis arietans':{identify:'Thick-bodied viper with a broad triangular head and bold chevron or crescent pattern in brown, tan and cream. The tail is short and the body may blend almost completely with leaf litter or sand.',behaviour:'Often remains motionless and may hiss loudly or inflate before striking when threatened. Watch where you step, keep well away and never prod a concealed snake.',diet:'Ambushes vertebrate prey. Record a prey item only if it is visible; a coiled position alone does not indicate hunting.',signs:'A wide side-to-side trail, shed skin and a flattened resting impression may occur but are not species-specific.',compare:'Gaboon viper is even more massively built with geometric patterning and horn-like nasal scales; rhombic night adders are smaller and differently marked. Distance is essential for all uncertain vipers.'},
 'Stigmochelys pardalis':{identify:'Large high-domed tortoise with each scute patterned by variable dark blotches, spots or radiating marks on a yellow to tan background. Older animals can become more uniformly coloured.',behaviour:'Walks and feeds in daylight when conditions permit, sheltering during temperature extremes. Do not lift, relocate or place it in a vehicle; allow it to cross safely in its chosen direction.',diet:'Primarily grazes and browses plant material. Record the actual plant part eaten rather than assuming diet from vegetation nearby.',signs:'Rounded elephant-like footprints, parallel claw marks, a shallow resting scrape and fibrous droppings may reveal passage.',compare:'African spurred tortoise can be larger, is more uniformly sandy and has prominent thigh spurs; pancake tortoise is extremely flat and associated with rock crevices.'},
 'Bitis gabonica':{identify:'Exceptionally stout viper with complex geometric pattern, pale rectangular dorsal marks, a broad leaf-shaped head and paired horn-like scales on the snout. The pattern is highly effective camouflage in forest litter.',behaviour:'Usually motionless and reluctant to move, relying on concealment. Never step around or over it, and do not approach for a close photograph.',diet:'Ambushes vertebrate prey from cover. Record feeding only when directly visible and from a substantial distance.',signs:'Heavy serpentine impressions and shed skin may be found in leaf litter but cannot safely confirm the species.',compare:'Rhinoceros viper has stronger blue, green and red patterning and more prominent nasal horns; puff adder has chevrons rather than the Gaboon viper’s geometric blocks.'},
 'Dispholidus typus':{identify:'Slender arboreal snake with very large eyes and a short blunt head; adult colour varies widely, including green, brown, black and combinations thereof. The body scales are distinctly keeled.',behaviour:'Usually moves through shrubs and trees and attempts escape, sometimes inflating the neck when defensive. Do not handle even an apparently calm individual.',diet:'Takes arboreal vertebrates including birds, eggs and reptiles. Record only directly observed prey and avoid disturbing nests to obtain a sighting.',signs:'Shed skin in vegetation and narrow climbing traces are rarely diagnostic; a clear long-lens photograph is more useful.',compare:'Green mambas have a longer, more coffin-shaped head and smaller-looking eyes; harmless green snakes can be similar. Identification from colour alone is unsafe.'},
 'Malacochersus tornieri':{identify:'Small, unusually flat and flexible tortoise with a patterned tan shell whose scutes often show dark radiating lines. Its low profile allows entry into narrow rock fissures.',behaviour:'Basks on rocky outcrops and retreats into crevices when alarmed. Never pull one from a crack or block its refuge.',diet:'Feeds on grasses and other plant material. Record the exact item being cropped rather than attributing nearby plants.',signs:'Small clawed tracks, droppings and polished access points near crevices may occur, but disturbance of shelter sites should be avoided.',compare:'Juvenile leopard tortoises are more domed and rigid; hinged tortoises have a different shell profile and movable rear shell section.'},
 'Chamaeleo dilepis':{identify:'Medium chameleon with a conspicuous movable flap behind each side of the head, a low casque and independently moving eyes. Colour changes with condition and is not a fixed identification character.',behaviour:'Moves slowly through shrubs and may flatten, rock or gape when threatened. Avoid touching, flash at close range or repeated repositioning for photographs.',diet:'Captures mostly invertebrates with the projecting tongue. Record prey only when seen; visual tracking does not confirm a strike.',signs:'Grasping footprints, droppings beneath perches and shed skin are subtle and not diagnostic.',compare:'Other chameleons differ in casque, horns, crests and body proportions. Confirm the neck flaps from more than one angle rather than relying on colour.'},
 'Mecistops cataphractus':{identify:'Medium to large crocodilian with a notably long narrow snout and armoured body, usually darker and more lightly built than broad-snouted crocodiles. Juveniles show clearer banding.',behaviour:'Secretive in forested waterways and may rest on banks or submerged timber. Observe quietly from a secure position without closing its route to water.',diet:'Takes fish and other available aquatic or waterside prey. Record only a visible feeding event.',signs:'Narrow haul-out trails, clawed tracks, tail drag and nesting disturbance may occur; similar crocodilians leave overlapping sign.',compare:'Nile and West African crocodiles have broader snouts; the African dwarf crocodile is smaller with a shorter, broader head. Distance and viewing angle can distort snout shape.'},
 'Python natalensis':{identify:'Very large, muscular python with complex brown and olive blotches, pale-edged head markings and heat-sensing lip pits. Pattern and proportions vary with age and lighting.',behaviour:'Uses cover, rocky refuges and water margins and may bask in open sites. Give it a wide berth and never crowd, touch or attempt to move it.',diet:'Constrains vertebrate prey. Do not interrupt feeding or describe prey unless it is clearly seen.',signs:'Broad slide marks, shed skin, burrow use and compressed vegetation indicate a large snake but usually not the exact species.',compare:'African rock python is closely related and taxonomic treatment varies; locality and expert examination are more reliable than a brief visual distinction.'},
 'Dendroaspis angusticeps':{identify:'Long slender snake usually bright to olive green, with a narrow head, smooth scales and a long tapering tail. Juveniles may be paler or differently toned.',behaviour:'Predominantly arboreal and generally retreats through dense foliage when disturbed. Keep well away and never shake vegetation or pursue it for a view.',diet:'Takes birds, eggs and small mammals among other prey. A position near a nest is not proof of predation.',signs:'Shed skin caught in vegetation may show scale detail but should not be handled; tracks are seldom useful.',compare:'Boomslang has proportionally larger eyes and a shorter head; harmless green snakes may be smaller or differently scaled. Treat every uncertain green snake with distance.'},
 'Bitis caudalis':{identify:'Small stout desert adder with a broad head, a single horn-like scale above each eye and blotched coloration matching sand or gravel. The short tail narrows abruptly.',behaviour:'Often partly buries itself and relies on camouflage, making it easy to approach accidentally. Scan the ground, wear suitable footwear and never probe sand or shelter sites.',diet:'Ambushes small vertebrates. Record prey only when clearly observed and do not disturb a buried snake.',signs:'Short sidewinding or serpentine tracks and a body-shaped depression may appear in fine substrate but overlap other desert snakes.',compare:'Other horned adders differ in horn number, head scales and pattern; juvenile puff adders lack the paired supraocular horns. Do not approach to inspect these details.'},
 'Naja haje':{identify:'Large cobra with a broad hood when defensive, robust body and highly variable brown, grey or dark coloration. The snout is rounded and the hood usually lacks a single dependable field mark.',behaviour:'Often attempts to escape but may raise the forebody and spread the hood when cornered. Back away slowly, provide space and never provoke a hood display.',diet:'Takes vertebrates and eggs. Record only directly visible food; movement into a burrow may indicate shelter.',signs:'Serpentine trails, shed skins and refuge use are not diagnostic. A distant photograph showing hood and head can support expert review.',compare:'Other African cobras overlap in colour and pattern. Snouted and spitting cobras require multiple characters and locality; assume defensive capability and maintain distance.'},
 'Naja mossambica':{identify:'Medium cobra usually brown to olive above with darker scale edges and a pinkish or yellow underside marked by dark throat bands. It spreads a hood when threatened.',behaviour:'May raise the forebody and project venom defensively toward the eyes. Keep far outside striking and spitting range, turn away and never attempt close photography or capture.',diet:'Takes amphibians, reptiles, birds and mammals. Record a food item only when clearly visible.',signs:'Shed skin and tracks cannot reliably separate it from other cobras; sightings near buildings should be handled by trained responders.',compare:'Snouted cobra is often larger and differs in throat and scale details; rinkhals has keeled scales and different defensive behaviour. Do not use close inspection to decide.'},
 'Varanus albigularis':{identify:'Heavy terrestrial monitor with a broad head, powerful limbs, long claws and a patterned grey-brown body bearing pale spots or bands. The tail is rounder and less laterally compressed than in the Nile monitor.',behaviour:'Forages on the ground, shelters in burrows or rock cavities and may inflate, hiss or lash the tail when cornered. Leave space and never handle it.',diet:'Takes many small animals, eggs, carrion and other available foods. Record direct feeding evidence rather than interpreting every dig.',signs:'Five-toed tracks with long claws, tail drags, excavations and burrow use are common clues; spoor can overlap Nile monitor away from water.',compare:'Nile monitor is more aquatic, generally more streamlined and has a strongly compressed swimming tail. Pattern alone varies and should not decide the identification.'},
 'Furcifer pardalis':{identify:'Large, strongly patterned chameleon with a prominent casque, granular scales and marked sexual colour differences; males are generally larger and more vividly patterned. Colour varies by individual and locality.',behaviour:'Moves through shrubs and trees, displaying by changing pattern, flattening or gaping. Observe without handling, staging interactions or relocating an animal.',diet:'Uses the projecting tongue to capture invertebrates and occasionally other small prey. Record only a clearly seen capture.',signs:'Grasping footprints, droppings beneath perches and shed fragments offer limited identification value.',compare:'Other Madagascar chameleons differ in rostral appendages, casque and flank pattern. Locale and structural features are more dependable than colour.'},
 'Chamaeleo namaquensis':{identify:'Large ground-oriented chameleon with a robust body, short tail, prominent casque and muted grey, brown or green pattern suited to desert substrates. It often shows pale flank patches.',behaviour:'Walks between low vegetation and burrows and may flatten or gape when approached. Avoid blocking shade, refuge or its path across a road.',diet:'Takes desert invertebrates and other small prey. Record tongue strikes and identifiable items without manipulating prey.',signs:'Distinctive grasping footprints and a tail trace may be visible in sand, but tracks alone should be treated cautiously.',compare:'Flap-necked chameleon is more arboreal with visible neck flaps and a proportionally longer tail. Desert colour change makes hue an unreliable distinction.'},
 'Centrochelys sulcata':{identify:'Very large sandy-coloured tortoise with a deeply grooved shell, thick elephantine limbs and prominent conical spurs on the thighs. Growth rings can be pronounced but do not give exact age.',behaviour:'Uses deep burrows to escape heat and cold and may be active in cooler parts of the day. Do not enter, collapse or obstruct a burrow.',diet:'Primarily consumes grasses and other vegetation. Record directly cropped material and never offer food.',signs:'Large rounded tracks, drag marks, fibrous dung and broad burrow entrances can be conspicuous in firm ground.',compare:'Leopard tortoise usually has dark patterned scutes and lacks the same prominent thigh spurs; introduced or captive individuals can occur outside expected settings.'},
 'Rhincodon typus':{identify:'Enormous broad-headed shark with a terminal mouth, three strong longitudinal ridges along each side and a unique pattern of pale spots and stripes on a dark back. Photograph the flank pattern without approaching or touching it.',behaviour:'Usually swims steadily near the surface or through the water column and may gather where food is concentrated. Keep clear of the head and tail, never ride the animal and follow the distance set by the local operator.',diet:'Filter-feeds on plankton, fish eggs and small schooling organisms. An open mouth indicates feeding only when water is visibly being filtered; do not bait or feed for a sighting.',signs:'A tall first dorsal fin, sweeping tail and spotted back may break the surface. Surface shadows and fin shapes alone are easily misread in glare.',compare:'Basking shark also filter-feeds but lacks the spot pattern and has very large gill openings; manta rays have broad wing-like pectoral fins and no shark-like tail fin.'},
 'Trichechus senegalensis':{identify:'Large rounded aquatic mammal with paddle-like forelimbs, a broad horizontal rounded tail and a wrinkled muzzle bearing stiff sensory bristles. The body appears grey to brown and has no dorsal fin.',behaviour:'Often surfaces quietly to breathe and may feed or rest in vegetated freshwater, estuarine or coastal settings. Observe without blocking channels, following, touching or separating animals.',diet:'Feeds mainly on aquatic and waterside vegetation, although other items may be taken. Record the plant or feeding action only when it can be seen clearly.',signs:'Paired nostrils briefly appearing at the surface, circular ripples, cropped vegetation and a broad tail wake can indicate a manatee but are not diagnostic alone.',compare:'Dugong has a fluked, whale-like tail and a more downturned snout; hippopotamus exposes eyes and ears prominently and has a very different head and body profile.'},
 'Dugong dugon':{identify:'Large grey marine mammal with paddle-like forelimbs, no dorsal fin, a downturned bristled muzzle and a deeply notched horizontal tail fluke. Adults can show pale tusks, but these may not be visible.',behaviour:'Surfaces quietly between dives and may travel alone, in pairs or in groups over shallow feeding grounds. Boats should slow, avoid cutting across travel paths and never pursue a surfacing animal.',diet:'Grazes seagrasses with the downturned muzzle. Feeding trails can support an observation, but they do not show when or how many dugongs used the site.',signs:'Smooth rolling surfacing, paired nostrils, a fluke seen before a dive and furrows through seagrass beds are useful clues.',compare:'African manatee has a rounded paddle-shaped tail rather than flukes and occurs in different aquatic settings; small cetaceans have a dorsal fin and a more pointed rostrum.'},
 'Megaptera novaeangliae':{identify:'Large whale with exceptionally long pectoral fins, a knobbled head and variable black-and-white tail-fluke pattern. The small dorsal fin sits on a hump that becomes prominent before a deep dive.',behaviour:'May breach, slap the surface, travel in loose groups or accompany a calf. Keep legal approach distances, avoid intercepting its course and never place a vessel between mother and calf.',diet:'Feeds on schooling fish and krill using baleen, sometimes with coordinated lunges or bubbles. Open-mouth or surface activity should be recorded without assuming the prey species.',signs:'Bushy blow, arched back, long pale pectoral fin and a raised fluke before a dive are strong field marks; fluke photographs can distinguish individuals.',compare:'Southern right whale lacks a dorsal fin and has head callosities; Bryde’s whale is more streamlined with a sickle-shaped dorsal fin and three ridges on the head.'},
 'Chelonia mydas':{identify:'Large sea turtle with a smooth oval shell, a small rounded head and a single pair of scales between the eyes. The shell pattern varies in brown, olive and gold and is not reliably green.',behaviour:'Surfaces to breathe, rests on reefs or grazes in shallow water; females may nest on beaches. Never touch, chase, illuminate, obstruct or stand in front of a nesting turtle.',diet:'Adults feed heavily on seagrasses and algae in many areas, while younger animals take a broader range. Record actual bites or identified material rather than inferring diet from habitat.',signs:'Broad paired flipper tracks and a symmetrical body drag lead to nests on sand; grazed seagrass, breathing surfacings and resting forms may be seen underwater.',compare:'Hawksbill has a narrower pointed beak and overlapping shell scutes; loggerhead has a much larger head and five pairs of lateral shell scutes rather than four.'},
 'Dermochelys coriacea':{identify:'The largest sea turtle, with a dark leathery shell crossed by seven prominent longitudinal ridges and scattered pale spots. It lacks the hard scutes seen on other sea turtles.',behaviour:'Powerful oceanic swimmer that may forage offshore; nesting females move laboriously on beaches. Keep lights off, stay behind nesting turtles and avoid all contact with adults, hatchlings and nests.',diet:'Feeds predominantly on gelatinous animals such as jellyfish and salps. A turtle near floating material is not proof of feeding, and plastic can be a dangerous look-alike.',signs:'Very wide alternating flipper tracks, a deep central body drag and a large nest disturbance are distinctive on beaches; at sea the ridged back may show when surfacing.',compare:'All other African sea turtles have hard scuted shells; olive ridley can leave a superficially broad track but is much smaller and lacks the longitudinal ridges.'},
 'Tursiops truncatus':{identify:'Robust dolphin with a short well-defined beak, curved mouth line and tall falcate dorsal fin. Colour is usually dark grey above and paler below, with considerable variation among populations.',behaviour:'May travel, bow-ride, forage, rest or socialise in fluid groups. Do not chase, feed, swim into a group or repeatedly alter a vessel course to provoke bow-riding.',diet:'Takes fish, squid and other marine prey using varied hunting tactics. Birds or surface splashes near dolphins do not by themselves identify a feeding event.',signs:'Regular rolling surfacings, a curved dorsal fin, splashes and coordinated direction changes can reveal a group; photographs of dorsal-fin edges can distinguish individuals.',compare:'Indo-Pacific bottlenose dolphin is often slimmer with ventral spotting in adults, but field separation may require locality and expert review; humpback dolphins have a longer beak and a distinctive dorsal hump.'},
 'Mobula alfredi':{identify:'Very large ray with broad triangular wings, forward-projecting cephalic lobes and a long tail without a functional sting. Dorsal markings and the spot pattern on the belly can identify individuals.',behaviour:'Glides, circles cleaning stations and may feed near the surface. Remain to the side, avoid blocking its path or descending onto a cleaning station, and never touch or ride it.',diet:'Filters zooplankton and small organisms using the cephalic lobes to funnel water. Open cephalic lobes and repeated feeding loops are stronger evidence than simple surface swimming.',signs:'Dark wing tips breaking the surface, a broad underwater silhouette, barrel rolls and feeding chains are conspicuous; size is difficult to judge without scale.',compare:'Oceanic manta ray usually grows larger and differs in shoulder pattern, mouth shading and ventral markings; devil rays are generally smaller with different head and tail features.'},
 'Latimeria chalumnae':{identify:'Heavy deep-water fish with fleshy lobed paired fins, thick overlapping scales, pale blotches and a distinctive three-lobed tail. Reliable identification normally comes from remotely operated vehicles, submersibles or documented catches.',behaviour:'Usually hovers or drifts near steep rocky habitat and caves, using paired fins in alternating patterns. Never seek to disturb, capture or handle one for an observation.',diet:'Takes fish and cephalopods. Feeding is rarely witnessed; prey claims should be based on direct imagery or published examination, not posture.',signs:'There is no practical surface sign. Depth, rocky setting and clear imagery of the lobed fins and tail are essential evidence.',compare:'No other living African marine fish combines the paired fleshy lobe fins and three-lobed tail; large groupers lack both features and have conventional rayed fins.'},
 'Mobula birostris':{identify:'The largest ray, with extremely broad triangular wings, cephalic lobes and a long whip-like tail. The dorsal shoulder pattern is commonly T-shaped, while ventral spot patterns can identify individuals.',behaviour:'Travels through open water, visits cleaning sites and may aggregate to feed. Approach slowly from the side, never encircle or touch it, and leave cleaning stations unobstructed.',diet:'Filter-feeds on zooplankton and small schooling organisms. Feeding loops, open cephalic lobes and visible plankton concentration provide useful context.',signs:'A huge dark silhouette, wing tips at the surface, looping dives and occasional leaps can reveal a manta; distance makes size alone unreliable.',compare:'Reef manta ray is generally smaller and commonly shows a different Y-shaped shoulder pattern, but colour varies and photographs of dorsal and ventral surfaces support expert confirmation.'},
 'Carcharodon carcharias':{identify:'Large, powerfully built shark with a conical snout, tall triangular first dorsal fin and strong contrast between dark upper body and white underside. Teeth are broad and triangular with serrated edges.',behaviour:'May cruise, investigate objects or accelerate rapidly around prey. Observe only through a responsible operator, keep limbs and equipment inside the vessel or approved enclosure and never feed independently.',diet:'Predates fish and marine mammals and also scavenges. A shark beside a carcass has not necessarily made the kill; record the sequence actually observed.',signs:'A high triangular dorsal fin, powerful crescent tail and straight purposeful wake can be visible near the surface, but fin-only identification is unreliable.',compare:'Shortfin mako is slimmer with a more pointed snout and different teeth; bull shark is stockier with a blunter snout and lacks the same sharply contrasting body pattern.'},
 'Galeocerdo cuvier':{identify:'Large robust shark with a broad blunt head, long upper tail lobe and dark vertical bars or spots that are strongest in younger animals and may fade with age.',behaviour:'Often cruises steadily in coastal or offshore habitats and may investigate food or vessels. Keep a controlled distance, never hand-feed and follow the instructions of the responsible operator.',diet:'An opportunistic predator and scavenger taking a very broad range of prey. Do not infer a diet item from debris or remains unless feeding is directly observed.',signs:'Broad head, long sweeping tail, striped flanks and a low rolling swim can aid recognition underwater; the dorsal fin alone is not diagnostic.',compare:'Bull shark has a shorter blunt snout and no tiger-like bars; zebra shark is spotted as an adult, has strong body ridges and rests on the seabed.'},
 'Carcharhinus leucas':{identify:'Heavy-bodied shark with a very short broad snout, small eyes and a tall triangular first dorsal fin. The back is grey, the underside pale and juveniles may have darker fin tips.',behaviour:'Uses coastal, estuarine and freshwater environments and may patrol turbid shallows. Avoid entering water around feeding activity, fish waste or poor visibility and never attempt close interaction.',diet:'Takes fishes and other aquatic or terrestrial prey opportunistically. Proximity to a school or carcass does not establish a feeding event.',signs:'A stocky silhouette and direct swimming close to shore can suggest bull shark, but murky-water sightings demand caution and should remain provisional.',compare:'Great white has a more conical snout, larger crescent tail and stronger dark-to-white contrast; similar requiem sharks often need fin proportions, dentition and locality for confirmation.'},
 'Sphyrna lewini':{identify:'Large hammerhead whose broad head has a central notch and smaller indentations along the front edge, creating a scalloped outline. The first dorsal fin is tall and the body grey-brown above.',behaviour:'May form large daytime schools and disperse to forage. Do not swim into or split a school, block travel corridors or crowd cleaning stations.',diet:'Takes fishes, rays, cephalopods and other marine animals. A circling or lowered-head posture is not by itself evidence of feeding.',signs:'The hammer-shaped head, tall dorsal fin and schooling silhouette are distinctive underwater; from the surface, a fin cannot reliably identify a hammerhead species.',compare:'Great hammerhead has a straighter front head margin with a central notch and a very tall sickle-shaped dorsal fin; smooth hammerhead lacks the central indentation.'},
 'Eretmochelys imbricata':{identify:'Medium sea turtle with a narrow pointed bird-like beak and overlapping shell scutes that create a serrated rear edge. The shell is richly mottled amber, brown and dark, but colour varies.',behaviour:'Often forages around reefs and rests under ledges; females nest on beaches. Never touch, chase or pull one from cover, and keep behind any nesting female with lights off.',diet:'Feeds heavily on sponges in many reef systems and also takes other invertebrates. Record visible bites and substrate rather than assuming every reef visit is feeding.',signs:'Narrow asymmetrical flipper tracks may lead through beach vegetation; underwater, the pointed beak and use of reef crevices are useful clues.',compare:'Green turtle has a rounder head, non-overlapping scutes and a smoother shell edge; loggerhead has a much larger head and lacks the hawksbill’s sharply hooked beak.'},
 'Caretta caretta':{identify:'Large sea turtle with an exceptionally broad head, powerful jaws, reddish-brown shell and five pairs of lateral scutes. The shell is more heart-shaped than the smooth oval of a green turtle.',behaviour:'Forages over reefs and seabeds and migrates through open water; females nest on sandy beaches. Give surfacing turtles space and never illuminate, obstruct or touch a nesting animal.',diet:'Crushes hard-shelled molluscs and crustaceans and takes other marine prey. A turtle inspecting the seabed does not confirm what it has eaten.',signs:'Broad alternating flipper tracks, a central body drag and nest chamber disturbance occur on beaches; surfacing reveals the large head before the shell.',compare:'Green turtle has a smaller rounded head and four pairs of lateral scutes; olive ridley is smaller and more uniformly olive with a variable number of lateral scutes.'},
 'Eubalaena australis':{identify:'Massive dark whale with no dorsal fin, a broad arched mouth and rough pale callosities on the head. The V-shaped blow may be visible in calm conditions, while belly patches vary individually.',behaviour:'Often moves slowly near the surface and may rest, socialise or accompany a calf. Maintain regulated distance, reduce speed and never approach between a mother and calf.',diet:'Filter-feeds on zooplankton using long baleen plates. Open-mouth movement through prey-rich water is stronger evidence of feeding than a simple surface skim.',signs:'V-shaped blow, smooth back without a dorsal fin, head callosities and broad triangular tail flukes are key clues; callosity patterns can distinguish individuals.',compare:'Humpback whale has a dorsal fin, knobbled head and very long pectoral fins; bowhead does not occur in African waters and has no head callosities.'},
 'Balaenoptera edeni':{identify:'Streamlined baleen whale with three longitudinal ridges on top of the head and a tall curved dorsal fin set well back. Identification at sea can be difficult because several rorquals overlap in shape.',behaviour:'May surface irregularly, change direction quickly or lunge through schooling prey. Vessels should avoid pursuit and parallel the animal only at a respectful regulated distance.',diet:'Feeds on schooling fishes, krill and other small prey by lunging and engulfing water. Feeding birds and bait balls add context but do not prove which whale species is present.',signs:'Low columnar blow, three head ridges, sharply curved dorsal fin and lack of a consistently raised fluke are useful when seen together.',compare:'Sei whale normally shows one central head ridge and a similarly tall dorsal fin; minke whale is smaller with a more pointed head. Clear photographs and expert review are often needed.'},
 'Leptoptilos crumenifer':{identify:'Very large dark-backed stork with a bare pink head and neck, massive tapered bill, white underparts and an inflatable pink throat pouch. In flight it retracts the neck and shows broad black-and-white wings.',behaviour:'Soars on thermals, gathers at carcasses, refuse sites and drying wetlands, and may stand with wings spread. Observe feeding groups without approaching carcasses or forcing birds to fly.',diet:'Scavenges carrion and refuse and also takes fish, frogs, insects and other small animals. Record the item actually swallowed because presence at a carcass does not prove what was eaten.',signs:'Large three-forward-one-back footprints, whitewash beneath roosts, dropped feathers and gatherings of soaring birds can reveal regular sites.',compare:'Adjutant storks do not occur wild in Africa; woolly-necked stork is smaller, feather-headed and lacks the throat pouch. A lappet-faced vulture has a hooked bill and fully feathered body.'},
 'Balearica regulorum':{identify:'Tall grey crane with a golden crown of stiff feathers, white cheek patch, red throat wattle and black-and-white wings carrying chestnut and gold. The neck is pale grey rather than black.',behaviour:'Forages in pairs or flocks, performs elaborate dances and roosts in trees or shallow wetlands. Keep away from display, nesting and roost sites and never use playback to draw birds closer.',diet:'Takes seeds, shoots, insects and other small animals, often while walking through grass or shallow water. Pecking alone does not identify the food.',signs:'Long three-toed tracks without webbing, probing marks, feathers and repeated calls around wetlands may indicate use, but nests should never be searched for closely.',compare:'Black crowned crane has a darker neck and different cheek colouring; wattled crane is larger, lacks the golden crown and has white neck and wattles.'},
 'Phoeniconaias minor':{identify:'Small flamingo with deep pink-red legs, a dark crimson bill that appears mostly black at distance and bright pink plumage in strongly coloured adults. The head and neck are proportionally compact.',behaviour:'Feeds and rests in dense flocks, sometimes forming coordinated lines or circles. View colonies and feeding concentrations from established points without entering the water or using drones overhead.',diet:'Filters microscopic algae and other tiny organisms with the specialised bill held inverted. Head-down sweeping is reliable feeding behaviour, but prey cannot be identified by eye.',signs:'Webbed tracks, shallow feeding furrows, feathers and large pink rafts on saline water are conspicuous; breeding sites are highly disturbance-sensitive.',compare:'Greater flamingo is noticeably larger and paler with a pink bill tipped black; size comparison within a mixed flock is more dependable than colour alone.'},
 'Acryllium vulturinum':{identify:'Large guineafowl with a bare blue head, long narrow neck, dark body finely spotted white and striking cobalt, black and white lance-shaped breast feathers. The tail and legs are relatively long.',behaviour:'Runs in cohesive terrestrial groups, dust-bathes and usually flies only when pressed. Stop well short of a feeding flock and never herd birds toward a road for photographs.',diet:'Takes seeds, fruits, shoots and invertebrates gathered from the ground. Scratching indicates foraging but not the exact item eaten.',signs:'Three-toed walking tracks, scratching, dust-baths, droppings and loose spotted feathers can mark regularly used ground.',compare:'Helmeted guineafowl has a bony casque, shorter neck and evenly spotted rounded body; crested guineafowl has a black feather crest and no vulturine breast plumes.'},
 'Spheniscus demersus':{identify:'Medium black-and-white penguin with a black facial mask, a single black chest band and a bare pink patch above each eye. Individual black spots on the white chest form a distinctive pattern.',behaviour:'Swims and porpoises at sea, rests in groups and nests in burrows or sheltered scrapes. Remain on marked paths, never block a bird travelling between sea and nest, and keep dogs away.',diet:'Pursues small schooling fish and squid underwater. A returning bird may carry food internally, so prey should not be inferred without direct observation.',signs:'Webbed footprints, guano, moulted feathers, burrow entrances and well-worn commuting paths are common at colonies; avoid every nest cavity.',compare:'Magellanic penguin has two black chest bands and does not normally breed in Africa; juvenile African penguins are blue-grey and lack the crisp adult face pattern.'},
 'Torgos tracheliotos':{identify:'Huge dark vulture with a heavy pale hooked bill, bare pink-red head, fleshy facial folds and white thighs that can look like trousers. Broad wings and a short wedge-shaped tail show in flight.',behaviour:'Soars widely and often dominates other scavengers at a carcass, using its powerful bill to open tough hide. Remain in the vehicle or at distance so feeding birds do not abandon the carcass.',diet:'Scavenges skin, tendons, meat and other carcass material and may take small live prey. Arrival first does not prove that the bird found or killed the animal.',signs:'Large tracks around carcasses, heavy wing impressions, whitewash at roosts and an immense soaring silhouette are useful clues.',compare:'White-headed vulture is smaller with a white downy head and patterned wings; hooded vulture is much smaller and slender-billed. Cinereous vulture is not a normal African safari species.'},
 'Merops bullockoides':{identify:'Slender, colourful bee-eater with a white forehead, red throat, black eye-mask, green-blue back and pale underparts. Adults have a square-ended tail without long central streamers.',behaviour:'Perches communally, sallies after flying insects and nests colonially in holes excavated in vertical riverbanks. Watch colonies from across the channel or a substantial distance and avoid playback.',diet:'Catches flying insects and often returns to a perch to remove a sting before swallowing. A sally is a hunting attempt; record prey only when visible.',signs:'Rows of round bank holes, favourite exposed perches, pellets containing insect fragments and repeated swooping flights mark a colony.',compare:'Little bee-eater is smaller and mostly green with a black gorget; southern carmine bee-eater is much larger and predominantly carmine.'},
 'Corythaeola cristata':{identify:'Africa’s largest turaco, with blue-grey body, greenish breast, long broad tail, heavy yellow-and-red bill and an upright blue-black crest. It lacks the crimson flight feathers typical of many smaller turacos.',behaviour:'Moves through the canopy in pairs or groups with bounding hops and short glides and gives loud resonant calls. Observe from existing trails without shaking fruiting branches or using playback.',diet:'Feeds mainly on fruit and also takes leaves, buds and flowers. Record the plant and swallowed item when visible rather than assuming every canopy visit is feeding.',signs:'Large fallen feathers, fruit debris, droppings containing seeds and distinctive rolling calls can reveal a hidden group.',compare:'Ross’s and purple-crested turacos are smaller, more vividly coloured and flash crimson wings; grey go-away-birds are slimmer and uniformly grey.'},
 'Upupa africana':{identify:'Cinnamon-orange bird with bold black-and-white rounded wings, long down-curved bill and a fan-shaped crest tipped black. The crest is often folded and should not be expected on every sighting.',behaviour:'Walks and probes open ground, flicks the crest when alert and flies with a buoyant butterfly-like action. Give nest cavities space and do not repeatedly flush a feeding bird.',diet:'Probes for insects, larvae and other small invertebrates in soil, dung and leaf litter. A probe is feeding behaviour, but the prey may remain unseen.',signs:'Small walking tracks, narrow probe holes, droppings and the repeated hollow call may reveal presence near short grass or woodland.',compare:'Woodhoopoes have glossy dark plumage, longer tails and often move in vocal groups through trees; scimitarbills are darker and lack the erectile fan crest.'},
 'Pelecanus onocrotalus':{identify:'Enormous pale pelican with a very long bill and extensible yellowish throat pouch, black flight feathers and pinkish facial skin and legs in adults. The neck is folded back in flight.',behaviour:'Fishes alone or cooperatively, rests in dense groups and soars in formation on broad wings. Boats should avoid driving through feeding lines, roosts or breeding aggregations.',diet:'Catches mainly fish by scooping, sometimes herding them cooperatively. A dipped bill may be drinking or bathing; swallowing and coordinated herding strengthen feeding evidence.',signs:'Large webbed footprints, feathers, whitewash and groups circling on thermals or aligned on water are conspicuous signs.',compare:'Pink-backed pelican is smaller and greyer with a pink-tinged back; white storks lack the pouch and fly with the neck extended.'},
 'Actophilornis africanus':{identify:'Long-legged wetland bird with chestnut body, white face and fore-neck, blue frontal shield and extremely elongated toes that spread weight across floating vegetation. In flight the yellow wings contrast strongly.',behaviour:'Walks over lily pads, calls sharply and may defend floating territories. Adults sometimes carry chicks under the wings; never approach to provoke or photograph this behaviour.',diet:'Picks insects, small aquatic animals and seeds from vegetation and the water surface. Record a captured item only when clearly seen.',signs:'Very long widely spread toe marks on mud, disturbed floating leaves, fine droppings and repeated pathways through vegetation can mark use.',compare:'Lesser jacana is smaller and more cryptically streaked; immature African jacanas lack the adult colours but retain extraordinarily long toes.'},
 'Bucorvus abyssinicus':{identify:'Huge terrestrial hornbill with black plumage, white primary feathers visible in flight and a massive black bill topped by a casque. Adult males show mainly red bare facial skin; females have substantial blue areas.',behaviour:'Walks in pairs or small family groups, booming at dawn and foraging across open ground. Do not follow closely, imitate calls or approach nest cavities.',diet:'Takes insects, reptiles, small vertebrates, carrion and some plant material. Record prey only when it is visible in the bill or swallowed.',signs:'Large three-toed tracks, powerful probing holes, pellets, feathers and deep carrying calls can reveal a group beyond view.',compare:'Southern ground hornbill has red facial skin in both sexes and a different casque profile; both differ from arboreal hornbills by their massive size and walking habit.'},
 'Bugeranus carunculatus':{identify:'Very large crane with white neck and upper breast, dark back, black crown and a conspicuous white feathered wattle hanging below the throat. Long dark legs trail well behind in flight.',behaviour:'Usually occurs in pairs or small groups in shallow wetlands, probing slowly and defending breeding territories. Keep far outside wetland nesting areas and never use drones or playback.',diet:'Takes aquatic plant parts, tubers, seeds, insects and other small animals. Deep probing indicates foraging but does not identify the item extracted.',signs:'Large three-toed tracks, deep bill probes, droppings and repeated pathways through sedges can show use without locating a nest.',compare:'Grey crowned crane has a golden crown and grey neck; blue crane is smaller and blue-grey without a white neck or throat wattle.'},
 'Scopus umbretta':{identify:'Medium stocky brown waterbird with a long rear-pointing crest, heavy black bill and broad rounded wings. The silhouette of head and crest resembles a hammer, giving the bird its name.',behaviour:'Walks slowly in shallow water, often alone or in pairs, and builds an enormous domed stick nest with a side entrance. View nests from a distance because other species may also occupy them.',diet:'Takes frogs, fish, aquatic insects and other small animals, often stirring mud with the feet. Record prey only when it is captured or handled.',signs:'Three-toed tracks at water edges, shallow foot-stirring marks, large domed stick nests and a repeated yip-like call reveal territories.',compare:'Juvenile night herons are streaked and lack the rear crest and domed nest; shoebill is vastly larger, grey and has a huge shoe-shaped bill.'},
 'Aquila verreauxii':{identify:'Large black eagle with a clean white V across the back and rump and pale windows in the wings visible during flight. The yellow cere and feet contrast with the dark plumage.',behaviour:'Soars close to cliffs, often in pairs, and uses updraughts to contour along rock faces. Watch from established viewpoints and stay away from occupied ledges and display flights.',diet:'Frequently hunts hyraxes and also takes other suitable vertebrates. Presence above a colony does not prove a hunting attempt; record stoops, captures or prey remains carefully.',signs:'Whitewash and prey remains below remote ledges, large stick nests and paired contour-soaring are useful clues; never climb toward a nest.',compare:'Black-chested snake eagle shows white underparts and a dark head and chest; juvenile Verreaux’s eagles are brown and can resemble other large immature eagles.'},
 'Stephanoaetus coronatus':{identify:'Powerful forest eagle with a short broad wing, long barred tail, raised crest and heavily barred underparts in adults. The upperparts are dark and the legs are thick and feathered.',behaviour:'Uses canopy perches, gives display flights above forest and may carry prey through dense vegetation. Remain quiet near calling pairs and do not seek nests by playback.',diet:'Predates medium-sized mammals and birds. Alarm calls or prey remains alone do not establish a kill; note a witnessed chase, capture or carried item.',signs:'Large stick nests high in forest trees, plucking sites, bones and loud ringing calls can indicate a territory, but approaching nests risks disturbance.',compare:'African hawk-eagle is slimmer with longer-looking wings and contrasting adult underparts; martial eagle favours more open country and has spotted, not barred, underparts.'},
 'Gyps africanus':{identify:'Medium-large vulture with pale brown body, whitish back and rump, dark flight feathers, bare dark head and a relatively long thin neck. Adults show a pale collar at the neck base.',behaviour:'Soars in groups, descends rapidly when other scavengers locate food and feeds communally. Stay back from carcasses and roadkills so birds can land and depart safely.',diet:'Scavenges soft tissue from large carcasses and depends on access opened by stronger species. A circling bird may be travelling rather than searching directly below.',signs:'Concentrated tracks and feathers around carcasses, whitewash at roosts and spiralling groups on thermals mark regular activity.',compare:'Rüppell’s vulture has stronger pale scaling and pale bars on the underwing; Cape vulture is larger and paler with different underwing contrast.'},
 'Necrosyrtes monachus':{identify:'Small slender vulture with dark brown plumage, bare pinkish face, narrow hooked bill and a pale downy hood behind the head. Its wings and tail look long for its body size.',behaviour:'Often arrives quietly at carcasses, scraps, fish landings or settlements and can pick small pieces inaccessible to larger vultures. Avoid crowding or feeding birds around people.',diet:'Scavenges small carrion fragments, scraps and organic waste and also takes insects. Record the item handled because foraging around refuse is broad and variable.',signs:'Small vulture tracks, scattered scraps, roost whitewash and a light circling silhouette can indicate presence near settlements or carcasses.',compare:'Egyptian vulture is larger and adults are white with black flight feathers and a yellow face; white-backed vulture is much bulkier with a heavier bill.'},
 'Merops nubicoides':{identify:'Large bee-eater with vivid carmine body, turquoise-blue crown and rump, black eye-mask and long pointed central tail feathers in adults. Immatures are duller and shorter-tailed.',behaviour:'Forms large colonies in earthen banks, sallies from exposed perches and may follow large mammals or vehicles catching disturbed insects. Do not drive into flocks or approach nesting banks.',diet:'Catches flying insects, returning to a perch to handle them before swallowing. Following a mammal indicates foraging opportunity, not a special dependency on that species.',signs:'Dense rows of nest holes in banks, favourite perches, insect fragments and streams of commuting birds identify colony areas.',compare:'Northern carmine bee-eater has greenish-blue rather than turquoise crown pattern and overlaps only in some areas; white-fronted bee-eater is smaller and lacks the carmine body.'},
 'Corythornis cristatus':{identify:'Tiny kingfisher with bright electric-blue crown and back, orange face and underparts, white throat patches and a long straight dark bill. The crown is barred rather than uniformly coloured.',behaviour:'Perches low above still or slow water and dives steeply after prey, often returning to the same perch. Remain back from banks and do not clear vegetation for a photograph.',diet:'Takes small fish, aquatic insects and other tiny aquatic prey. A dive is an attempt; record success only if prey is seen.',signs:'A regular low perch, small splash points, fish scales or pellets and a thin high call may reveal a bird hidden beside water.',compare:'Half-collared kingfisher is larger and darker blue with white underparts; African pygmy kingfisher is more terrestrial, has lilac ear coverts and a red bill.'},
 'Numida meleagris':{identify:'Large round-bodied ground bird densely spotted white on dark grey, with a bare blue-and-red head and bony helmet or casque. The short tail droops and the back looks humped.',behaviour:'Walks and runs in noisy flocks, dust-bathes and flies strongly for short distances when pressed. Slow down around roadside groups and allow them to move without being chased.',diet:'Takes seeds, shoots, bulbs and many invertebrates by pecking and scratching. Ground disturbance alone does not identify the food.',signs:'Three-toed tracks, communal dust-baths, scratching, droppings and spotted feathers are common signs around feeding and roost sites.',compare:'Crested guineafowl has a curly black crest instead of a casque; vulturine guineafowl has a long blue neck and lance-shaped breast feathers.'},
 'Scotopelia peli':{identify:'Very large warm rufous-brown owl with dark streaking, dark eyes, an indistinct facial disc and unfeathered lower legs adapted to fishing. It lacks ear tufts.',behaviour:'Roosts quietly in large waterside trees and hunts from low branches over water, mostly in darkness. Never spotlight a roost repeatedly, imitate calls or approach a nest tree.',diet:'Catches mainly fish and also other aquatic prey from the water surface. A waterside perch is not evidence of a fishing attempt unless a strike is seen.',signs:'Fish scales, bones, large pellets, whitewash beneath riparian roosts and a deep carrying call can identify a used stretch of river.',compare:'Verreaux’s eagle-owl has ear tufts, pale eyelids and feathered legs; African fishing owl is smaller and more heavily spotted in areas where ranges approach.'},
 'Buphagus erythrorhynchus':{identify:'Medium brown oxpecker with a bright red bill, yellow eye-ring and pale buff rump visible in flight. Juveniles have a dark bill and duller eye area.',behaviour:'Climbs over large mammals, probing fur and wounds, and flies between hosts with sharp calls. Do not approach or manipulate host animals to improve the view.',diet:'Takes ticks and other ectoparasites and also feeds at wounds and on blood. Attendance on a mammal is foraging association, but the item should be recorded only when visible.',signs:'Calls around herds, pale-rumped flight, droppings on host resting sites and birds clinging to moving mammals are the most useful field evidence.',compare:'Yellow-billed oxpecker has a yellow bill base with red tip and generally paler rump; juveniles of both can be difficult and require range plus close photographs.'},
 'Buphagus africanus':{identify:'Medium brown oxpecker with a stout bill that is yellow at the base and red at the tip, a red eye and pale buff rump. Juveniles have a dark bill and muted facial colour.',behaviour:'Moves over large mammals in small groups, clinging sideways and searching ears, skin folds and wounds. Observe the host’s response and never move closer because the birds appear tolerant.',diet:'Takes ticks and other ectoparasites and may feed on blood or wound tissue. Record the actual action rather than labelling every contact as tick removal.',signs:'Hissing calls, pale-rumped flight and groups riding large mammals reveal presence more readily than ground signs.',compare:'Red-billed oxpecker has an entirely red adult bill and yellow eye-ring; immature birds overlap and may need locality and clear images for confirmation.'},
 'Nettapus auritus':{identify:'Very small compact waterfowl with short bill and rounded head. Adult males show a white face, glossy green ear patch and back, while females have a pale face crossed by a dark eye-stripe.',behaviour:'Swims among floating vegetation, flies swiftly and may perch on branches; pairs and small groups can be inconspicuous. Avoid pushing birds from sheltered coves or nesting cavities.',diet:'Feeds mainly on seeds and other parts of aquatic plants, with some small aquatic animals. Surface dabbling does not reveal the exact food item.',signs:'Tiny webbed tracks, fine droppings on floating leaves, small feather traces and narrow wakes through vegetation may mark use.',compare:'White-backed duck is larger, longer-bodied and dark-faced; juvenile and female pygmy geese require attention to the compact shape and facial pattern.'}
};
function observationCards(row){const guide=speciesFieldGuides[row?.[1]]||observationGuides[row?.[2]]||observationGuides.Mammal,specific=!!speciesFieldGuides[row?.[1]];return `<div class="field-guide-status">${specific?'Species-specific offline field notes':'Group-level observation framework'}</div><div class="observation-grid"><article><small>LOOK</small><strong>Identification</strong><p>${guide.identify}</p></article><article><small>WATCH</small><strong>Behaviour</strong><p>${guide.behaviour}</p></article><article><small>FEEDING</small><strong>Diet evidence</strong><p>${guide.diet}</p></article><article><small>TRACE</small><strong>Tracks & signs</strong><p>${guide.signs}</p></article><article><small>CHECK</small><strong>Similar species</strong><p>${guide.compare}</p></article></div>`}
function commonsValue(value){return String(value?.value||value||'').replace(/<[^>]*>/g,'').trim()}
function audioPanel(name,scientific){const recording=window.pocketWildlifeSounds?.[name],saved=savedAudioFor(scientific);return `<section class="profile-section audio-field-section" id="profileSounds"><div class="entry-kicker">SOUNDS</div><h3>Listen to ${profileSafe(name)}</h3>${recording?`<div class="verified-audio"><strong>Offline reference · ${profileSafe(recording.title)}</strong><audio controls preload="metadata" src="${profileSafe(recording.src)}">Audio playback is unavailable.</audio><small>${profileSafe(recording.credit)} · ${profileSafe(recording.license)}</small><a href="${profileSafe(recording.source)}" target="_blank" rel="noopener">Recording source and licence ↗</a></div>`:''}${saved.map(item=>audioResult(item,true)).join('')}<button class="find-audio" type="button" data-find-audio="${profileSafe(scientific)}" data-audio-name="${profileSafe(name)}">${navigator.onLine?'Loading attributed recordings…':'Check for more recordings online'}</button><div class="audio-search-results" aria-live="polite"></div><p class="profile-caution">Discovered results are matching audio files, not automatically verified animal calls. Confirm the title and source description before identification. Never play calls near wildlife; playback can disturb animals and alter behaviour.</p></section>`}
function audioResult(item,saved=false){pendingProfileAudio[item.id]=item;return `<article class="audio-result"><strong>${profileSafe(item.title)}</strong><audio controls preload="none" src="${profileSafe(item.url)}">Audio playback is unavailable.</audio><small>${profileSafe(item.creator)} · ${profileSafe(item.license)}${saved?' · saved offline':''}</small><div class="audio-result-actions"><a href="${profileSafe(item.source)}" target="_blank" rel="noopener">Source & licence ↗</a><button type="button" data-save-audio="${profileSafe(item.id)}" ${saved||!('caches'in window)?'disabled':''}>${saved?'✓ Saved offline':'Save offline'}</button></div></article>`}
async function findCommonsAudio(button){const box=button.parentElement.querySelector('.audio-search-results'),scientific=button.dataset.findAudio,name=button.dataset.audioName;button.disabled=true;button.textContent='Searching recordings…';box.innerHTML='<p>Checking Wikimedia Commons audio metadata…</p>';try{const queries=[scientific,`${name} animal sound`],responses=await Promise.all(queries.map(query=>profileJson(`https://commons.wikimedia.org/w/api.php?action=query&generator=search&gsrsearch=${encodeURIComponent(query)}&gsrnamespace=6&gsrlimit=25&prop=imageinfo&iiprop=url|mime|extmetadata&format=json&origin=*`))),seen=new Set(),audio=responses.flatMap(data=>Object.values(data.query?.pages||{})).map(page=>({page,info:page.imageinfo?.[0]})).filter(item=>item.info?.url&&String(item.info.mime).startsWith('audio/')&&!seen.has(item.info.url)&&seen.add(item.info.url)).slice(0,8).map(({page,info})=>{const meta=info.extmetadata||{},title=String(page.title||'').replace(/^File:/,''),id=`${scientific}|${info.url}`;return{id,scientific,title,url:info.url,creator:commonsValue(meta.Artist)||commonsValue(meta.Credit)||'Contributor not supplied',license:commonsValue(meta.LicenseShortName)||commonsValue(meta.UsageTerms)||'Licence not supplied',source:`https://commons.wikimedia.org/wiki/${encodeURIComponent(page.title)}`}});box.innerHTML=audio.length?audio.map(item=>audioResult(item,false)).join(''):'<div class="profile-unavailable">No matching recording was returned for this species.</div>'}catch(error){box.innerHTML='<div class="profile-unavailable">Recordings could not be reached. Saved sounds and connected calls still work offline.</div>'}finally{button.disabled=false;button.textContent='Refresh recordings'}}
async function openWildlifeProfile(scientific,focusSounds=false){
 const row=(window.pocketWildlife||[]).find(animal=>animal[1]===scientific),name=row?.[0]||scientific,page=row?.[4]||scientific,checked=new Date(),savedPhoto=readProfileMedia()[scientific];
 wildlifeDialog.showModal();wildlifeProfile.innerHTML='<p class="database-status">Building sourced field entry…</p>';
 const [taxonResult,summaryResult]=await Promise.allSettled([profileJson(`https://api.gbif.org/v1/species/match?name=${encodeURIComponent(scientific)}`),profileJson(`https://en.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(page)}`)]),taxon=taxonResult.status==='fulfilled'?taxonResult.value:null,summary=summaryResult.status==='fulfilled'?summaryResult.value:null,key=taxon?.usageKey||taxon?.speciesKey;
 let occurrence=null;if(key){try{occurrence=await profileJson(`https://api.gbif.org/v1/occurrence/search?taxon_key=${key}&limit=0&facet=country&facetLimit=12`)}catch{}}
 let mediaRecord=null;if(key){try{const mediaData=await profileJson(`https://api.gbif.org/v1/occurrence/search?taxon_key=${key}&media_type=StillImage&limit=20`);mediaRecord=mediaData.results?.find(item=>(item.media||[]).some(mediaItem=>mediaItem.identifier))||null}catch{}}
 const media=mediaRecord?.media?.find(item=>item.identifier),countries=(occurrence?.facets?.find(facet=>String(facet.field).toLowerCase()==='country')?.counts||[]).map(item=>({name:countryName(item.name),count:item.count})),classification=[['Kingdom',taxon?.kingdom],['Phylum',taxon?.phylum],['Class',taxon?.class],['Order',taxon?.order],['Family',taxon?.family],['Genus',taxon?.genus]].filter(item=>item[1]),photo=savedPhoto?.url||media?.identifier||summary?.originalimage?.source||summary?.thumbnail?.source,photoProvider=savedPhoto?.provider||(media?'GBIF occurrence media':'Wikimedia reference'),photoCredit=savedPhoto?.credit||media?.creator||media?.rightsHolder||mediaRecord?.institutionCode||'Contributor not supplied',photoLicense=savedPhoto?.license||media?.license||media?.rights||'Licence not supplied',photoSource=savedPhoto?.source||(mediaRecord?.key?`https://www.gbif.org/occurrence/${mediaRecord.key}`:summary?.content_urls?.desktop?.page);
 if(photo)pendingProfileMedia[scientific]={url:photo,provider:photoProvider,credit:photoCredit,license:photoLicense,source:photoSource||''};
 wildlifeProfile.innerHTML=`<div class="wildlife-profile-hero">${photo?`<img src="${profileSafe(photo)}" alt="${profileSafe(name)} photograph">`:'<div class="profile-photo-missing">Photograph unavailable offline</div>'}<div><p class="eyebrow">FIELD ENTRY</p><h2>${profileSafe(name)}</h2><em>${profileSafe(scientific)}</em><span>${profileSafe(row?.[2])}</span></div></div><section class="profile-section"><div class="entry-kicker">IDENTIFICATION CONTEXT</div><h3>About this species</h3><p>${profileSafe(summary?.extract,'A connected descriptive account is unavailable. The offline field notes below remain available.')}</p><div class="profile-habitat"><small>Pocketbook habitat index</small><strong>${profileSafe(row?.[3])}</strong></div><p class="profile-caution">Similar species, age, sex and local variation can cause mistakes.</p></section><section class="profile-section field-craft-section"><div class="entry-kicker">FIELD CRAFT · WORKS OFFLINE</div><h3>Identification, behaviour and sign</h3>${observationCards(row)}<p class="profile-caution">Use several features, keep a safe distance and confirm uncertain identifications with a qualified guide.</p><button class="profile-record" type="button" data-record-animal="${profileSafe(name)}">＋ Record this sighting</button></section>${audioPanel(name,scientific)}<section class="profile-section"><div class="entry-kicker">TAXONOMY</div><h3>Scientific classification</h3>${classification.length?`<div class="classification-grid">${classification.map(([rank,value])=>`<div><small>${rank}</small><strong>${profileSafe(value)}</strong></div>`).join('')}</div>`:'<div class="profile-unavailable">GBIF taxonomy could not be retrieved. The offline scientific name remains available.</div>'}</section><section class="profile-section"><div class="entry-kicker">OCCURRENCE EVIDENCE</div><h3>Countries represented in GBIF records</h3>${countries.length?`<div class="occurrence-list">${countries.map(country=>`<span><strong>${profileSafe(country.name)}</strong><small>${Number(country.count).toLocaleString()} records</small></span>`).join('')}</div><p class="profile-caution">These are database records, not a complete present-day range map.</p>`:'<div class="profile-unavailable">Recorded-country evidence is unavailable offline or was not returned.</div>'}</section><section class="profile-section"><div class="entry-kicker">CONSERVATION</div><h3>Check current status</h3><p>Open the authoritative assessment to confirm the current category and publication date.</p><div class="profile-links">${key?`<a href="https://www.gbif.org/species/${key}" target="_blank" rel="noopener">GBIF taxon entry ↗</a>`:''}<a href="https://www.iucnredlist.org/search?query=${encodeURIComponent(scientific)}&searchType=species" target="_blank" rel="noopener">IUCN Red List search ↗</a></div></section><div class="profile-sources"><strong>Sources checked ${checked.toLocaleString()}</strong><span>GBIF: taxonomy and occurrence evidence</span><span>Wikipedia/Wikimedia: descriptive reference and media</span><span>Wikimedia Commons: audio metadata and licences</span><small>Local guides and current conservation authorities remain essential.</small></div>`;
 if(photo){const hero=wildlifeProfile.querySelector('.wildlife-profile-hero');hero?.insertAdjacentHTML('afterend',`<div class="profile-media-credit"><strong>${savedPhoto?'Saved offline · ':''}${profileSafe(photoProvider)}</strong><span>${profileSafe(photoCredit)} · ${profileSafe(photoLicense)}</span>${photoSource?`<a href="${profileSafe(photoSource)}" target="_blank" rel="noopener">Open media record ↗</a>`:''}</div><div class="profile-media-save"><button type="button" data-save-profile-photo="${profileSafe(scientific)}" ${savedPhoto||!('caches'in window)?'disabled':''}>${savedPhoto?'✓ Photograph saved offline':('caches'in window?'Save photograph for offline use':'Offline photo saving unavailable')}</button>${savedPhoto?`<small>Saved ${profileSafe(new Date(savedPhoto.savedAt).toLocaleDateString())}. Attribution remains attached.</small>`:'<small>Saves this exact sourced photograph on this device. Availability depends on the provider permitting download.</small>'}</div>`)}
 const soundButton=wildlifeProfile.querySelector('[data-find-audio]');if(navigator.onLine&&soundButton)findCommonsAudio(soundButton);if(focusSounds)requestAnimationFrame(()=>document.getElementById('profileSounds')?.scrollIntoView({behavior:'smooth',block:'start'}));
}
wildlifeDialog.addEventListener('click',event=>{const audio=event.target.closest('[data-find-audio]');if(audio){findCommonsAudio(audio);return}const saveAudio=event.target.closest('[data-save-audio]');if(saveAudio){saveProfileAudio(saveAudio);return}const save=event.target.closest('[data-save-profile-photo]');if(save){saveProfileMedia(save.dataset.saveProfilePhoto);return}if(event.target.closest('[data-record-animal]'))wildlifeDialog.close()});
